import{d as C,C as y,o as D,c as S,a3 as r,E as a,j as i,a as e}from"./chunks/framework.D4-ViStF.js";const E=JSON.parse('{"title":"庄子·齐物论","description":"围绕地籁天籁、大知小知、道枢莫若以明、庄周梦蝶展开庄子的齐物思想。","frontmatter":{"title":"庄子·齐物论","description":"围绕地籁天籁、大知小知、道枢莫若以明、庄周梦蝶展开庄子的齐物思想。","category":"guide","aliases":["齐物论","庄子齐物论","zhuangzi chapter 02"],"source":["《庄子》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-02.md","filePath":"daoism/zhuang-zi/chapter-02.md","lastUpdated":1788516578000}'),V={name:"daoism/zhuang-zi/chapter-02.md"},I=C({...V,setup(N){const m=[{id:"nanguo_s1",label:"南郭子綦隐机而坐……似丧其耦",sentences:[[{text:"南郭子綦",glossary:"nanguoziq"},{text:"隐机",glossary:"yinji"},"而",{text:"坐",glossary:"zuo"},"，仰天而",{text:"嘘",glossary:"xu"},"，",{text:"苔焉",glossary:"taiyan"},{text:"似丧其耦",glossary:"sanggou"},"。"]]},{id:"nanguo_s2",label:"颜成子游立侍乎前……非昔之隐机者也",sentences:[[{text:"颜成子游",glossary:"yanchengziyou"},{text:"立侍乎前",glossary:"lishihqian"},"，曰："],["「",{text:"何居乎",glossary:"hejuhu"},"？",{text:"形固",glossary:"xinggu"},{text:"可",glossary:"ke"},{text:"使",glossary:"shi"},{text:"如",glossary:"ru"},{text:"槁木",glossary:"gaomo"},"，",{text:"而",glossary:"er_conj"},{text:"心固",glossary:"xingu"},"可使如",{text:"死灰",glossary:"sihui"},"乎？"],[{text:"今",glossary:"jin"},"之",{text:"隐机者",glossary:"yinjizhe"},"，",{text:"非",glossary:"fei"},{text:"昔之",glossary:"xizhi"},"隐机者也？」"]]},{id:"nanguo_s3",label:"子綦曰……未闻天籁夫",sentences:[[{text:"子綦",glossary:"ziq"},"曰："],["「",{text:"偃",glossary:"yan"},"，",{text:"不亦善乎",glossary:"buyishanhu"},{text:"而问之也",glossary:"er_2nd"},"！"],[{text:"今者",glossary:"jinzhe"},{text:"吾丧我",glossary:"wusangwo"},"，",{text:"汝知之乎",glossary:"ruzhizhi"},"？"],[{text:"女",glossary:"nv_ru"},{text:"闻",glossary:"wen"},{text:"人籁",glossary:"renlai"},"而",{text:"未闻",glossary:"weiweng"},{text:"地籁",glossary:"dilai"},"，女闻地籁而未闻",{text:"天籁",glossary:"tianlai"},{text:"夫",glossary:"fu_modal"},"！」"]]}],o=[{id:"nanguoziq",term:"南郭子綦",pinyin:"nán guō zǐ qí",meaning:"人名，南郭为复姓，子綦为名。庄子笔下的得道者形象。"},{id:"yinji",term:"隐机",pinyin:"yǐn jī",meaning:"靠着几案。隐：倚靠；机：矮几，古人席地而坐时凭倚的小桌。"},{id:"zuo",term:"坐",pinyin:"zuò",meaning:"席地而坐。古人「坐」为跪坐，非现代椅坐。"},{id:"xu",term:"嘘",pinyin:"xū",meaning:"缓缓吐气，长叹。非现代「嘘声制止」义。【古今异义】"},{id:"taiyan",term:"苔焉",pinyin:"tuí yān",meaning:"茫然失神的样子。苔通「颓」，颓然。【通假字】⚠️ 考试务必写「通颓」，不可写「像青苔一样」。"},{id:"sanggou",term:"似丧其耦",pinyin:"sì sàng qí ǒu",meaning:"好像失去了与自己对立的另一半。耦：对立面、配偶。暗示「我」是与「吾」对立的另一半，丧耦即丧我。"},{id:"yanchengziyou",term:"颜成子游",pinyin:"yán chéng zǐ yóu",meaning:"人名，子綦的弟子，颜成为复姓，子游为字。"},{id:"lishihqian",term:"立侍乎前",pinyin:"lì shì hū qián",meaning:"站立侍奉在面前。乎：介词，相当于「于」。"},{id:"hejuhu",term:"何居乎",pinyin:"hé jū hū",meaning:"这是怎么了？居：语气助词，无实义。【古今异义】⚠️ 非「居住」。"},{id:"xinggu",term:"形固",pinyin:"xíng gù",meaning:"形体难道……固：难道，表反问语气。【古今异义】非「固然/本来」。"},{id:"xingu",term:"心固",pinyin:"xīn gù",meaning:"内心难道……与「形固」对举，固：难道，表反问。【古今异义】"},{id:"ke",term:"可",pinyin:"kě",meaning:"能够，可以。助动词。"},{id:"shi",term:"使",pinyin:"shǐ",meaning:"让、使得。兼语式动词：使（之）如槁木。"},{id:"ru",term:"如",pinyin:"rú",meaning:"像、如同。比况连词。"},{id:"gaomo",term:"槁木",pinyin:"gǎo mù",meaning:"枯木。槁：枯干。与「死灰」对举，形容形体与心灵皆归于寂灭。"},{id:"er_conj",term:"而",pinyin:"ér",meaning:"连词，表并列或递进，连接「形固……」与「心固……」两句。"},{id:"sihui",term:"死灰",pinyin:"sǐ huī",meaning:"熄灭的灰烬。比喻心灵毫无生气、不再有情绪波动。"},{id:"jin",term:"今",pinyin:"jīn",meaning:"现在、此刻。与下文「昔」对举。"},{id:"yinjizhe",term:"隐机者",pinyin:"yǐn jī zhě",meaning:"靠着几案的那个人。者：代词，指代人。"},{id:"fei",term:"非",pinyin:"fēi",meaning:"不是。判断句否定式「非……也」的否定词。"},{id:"xizhi",term:"昔之",pinyin:"xī zhī",meaning:"从前的、往昔的。昔：过去；之：结构助词，修饰后文「隐机者」。"},{id:"ziq",term:"子綦",pinyin:"zǐ qí",meaning:"即南郭子綦，此处省去复姓「南郭」，为行文简洁。"},{id:"yan",term:"偃",pinyin:"yǎn",meaning:"子游之名（名偃，字子游）。师长直呼弟子之名，表亲切。"},{id:"buyishanhu",term:"不亦善乎",pinyin:"bù yì shàn hū",meaning:"不也很好吗。固定句式「不亦……乎」，表委婉反问，此处含赞许之意。"},{id:"er_2nd",term:"而问之也",pinyin:"ér wèn zhī yě",meaning:"你这样问。而：第二人称代词「你」。【古今异义】⚠️ 非连词。"},{id:"jinzhe",term:"今者",pinyin:"jīn zhě",meaning:"刚才。者：时间助词，附于时间词后，无实义。"},{id:"wusangwo",term:"吾丧我",pinyin:"wú sàng wǒ",meaning:"我放下了小我。吾：觉悟的主体意识；我：被执念束缚的小我；丧：放下、超越，非「死丧」。【核心命题】⚠️ 丧我是主动超越，不是消亡。"},{id:"ruzhizhi",term:"汝知之乎",pinyin:"rǔ zhī zhī hū",meaning:"你知道吗？汝：第二人称「你」；之：代词，指「吾丧我」这件事。"},{id:"nv_ru",term:"女",pinyin:"rǔ",meaning:"通「汝」，你。【通假字】"},{id:"wen",term:"闻",pinyin:"wén",meaning:"听到、听说。此处为感官动词，非「见闻/名声」义。"},{id:"renlai",term:"人籁",pinyin:"rén lài",meaning:"人为发出的声音。籁：孔穴发出的声音。对应逍遥游：世俗之知，有意为之，有所待。"},{id:"weiweng",term:"未闻",pinyin:"wèi wén",meaning:"不曾听到。未：副词，表否定，强调「尚未」而非「不」。"},{id:"dilai",term:"地籁",pinyin:"dì lài",meaning:"大地的声音，风吹万物孔穴所发之声。对应逍遥游：列子御风，依赖外物，有所待。"},{id:"tianlai",term:"天籁",pinyin:"tiān lài",meaning:"天地自然本真之声，万物各自发声而无主宰。最高层次。对应逍遥游：至人无己，无待自然，绝对自由。"},{id:"fu_modal",term:"夫",pinyin:"fú",meaning:"句末语气词，表感叹。⚠️ 注意：句末「夫」为语气词；句首「夫」才是发语词，二者不同。"}],h=[{id:"tianlai_s1",label:"子游曰：敢问其方",sentences:[[{text:"子游",glossary:"ziyou"},"曰：「",{text:"敢问其方",glossary:"ganwenfang"},"。」"]]},{id:"tianlai_s2",label:"夫大块噫气……众窍为虚",sentences:[["子綦曰：「",{text:"夫",glossary:"fu_preface"},{text:"大块",glossary:"dakuai"},{text:"噫",glossary:"yi_qi"},{text:"气",glossary:"qi_feng"},"，其名为风。"],[{text:"是唯",glossary:"shiwei"},"无作，作则",{text:"万窍怒呺",glossary:"wanqiaonuhao"},"。"],["而",{text:"独",glossary:"du"},{text:"不闻之",glossary:"buwen"},{text:"翏翏",glossary:"liuliu"},"乎？"],[{text:"山林",glossary:"shanlin"},"之",{text:"畏佳",glossary:"weijia"},"，"],[{text:"大木百围",glossary:"damubawei"},"之",{text:"窍穴",glossary:"qiaoxue"},"，"],["似鼻，似口，似耳，",{text:"似笄",glossary:"sijī"},"，",{text:"似圈",glossary:"sijuan"},"，",{text:"似臼",glossary:"sijiu"},"，",{text:"似洼者",glossary:"siwa"},"，",{text:"似污者",glossary:"siwu"},"。"],[{text:"激者",glossary:"jizhe"},"、",{text:"謞者",glossary:"xiaozhe"},"、",{text:"叱者",glossary:"chizhe"},"、",{text:"吸者",glossary:"xizhe"},"、",{text:"叫者",glossary:"jiaozhe"},"、",{text:"譹者",glossary:"haozhe"},"、",{text:"宎者",glossary:"yaozhe"},"、",{text:"咬者",glossary:"yaozhe2"},"，"],[{text:"前者",glossary:"qianzhe"},{text:"唱",glossary:"chang"},{text:"于",glossary:"yu_sound"},{text:"而",glossary:"er_sui"},{text:"随者",glossary:"suizhe"},{text:"唱喁",glossary:"changyong"},"，"],[{text:"泠风则小和",glossary:"lingfeng"},"，",{text:"飘风则大和",glossary:"piaofeng"},"，"],[{text:"厉风",glossary:"lifeng"},{text:"济",glossary:"ji_stop"},"则",{text:"众窍为虚",glossary:"wanqiaoweixu"},"。"],["而",{text:"独不见之",glossary:"dubujianzhi"},{text:"调调之",glossary:"diaodiao"},{text:"刁刁乎",glossary:"diaodiao"},"？」"]]},{id:"tianlai_s3",label:"地籁则众窍是已……敢问天籁",sentences:[["子游曰：「",{text:"地籁",glossary:"dilai2"},"则",{text:"众窍",glossary:"zhongqiao"},{text:"是已",glossary:"shiye"},"，"],[{text:"人籁",glossary:"renlai2"},"则",{text:"比竹",glossary:"bizhu"},{text:"是已",glossary:"shiye"},"，"],["敢问",{text:"天籁",glossary:"tianlai2"},"。」"]]},{id:"tianlai_s4",label:"夫吹万不同……怒者其谁邪",sentences:[["子綦曰：「",{text:"夫",glossary:"fu_preface"},{text:"吹万不同",glossary:"chuiwan"},"，而",{text:"使其自己也",glossary:"shiqiziji"},"。"],[{text:"咸",glossary:"xian"},{text:"其自取",glossary:"ziqu"},"，",{text:"怒者其谁邪",glossary:"nuzhequishei"},"？」"]]}],l=[{id:"ziyou",term:"子游",pinyin:"zǐ yóu",meaning:"即颜成子游，子綦之弟子，承接上文继续发问。"},{id:"ganwenfang",term:"敢问其方",pinyin:"gǎn wèn qí fāng",meaning:"冒昧请问其中的道理。敢：谦辞，表示冒昧；方：道理、方法。"},{id:"fu_preface",term:"夫",pinyin:"fú",meaning:"发语词，句首语气词，无实义，引起下文。⚠️ 与句末语气词「夫」不同。"},{id:"dakuai",term:"大块",pinyin:"dà kuài",meaning:"大地，指天地自然整体。块：土块，引申为大地。"},{id:"yi_qi",term:"噫",pinyin:"yī",meaning:"吐气、呼气。大地呼气即为风，拟人化写法。"},{id:"qi_feng",term:"气",pinyin:"qì",meaning:"气息，此处指大地所呼出的气，即风的本质。"},{id:"shiwei",term:"是唯",pinyin:"shì wéi",meaning:"这（风）只要。是：指示代词，指风；唯：只要，表条件。"},{id:"wanqiaonuhao",term:"万窍怒呺",pinyin:"wàn qiào nù háo",meaning:"万千孔穴愤怒地呼号。窍：孔穴；怒：猛烈，形容词作状语；呺：大声呼号。"},{id:"du",term:"独",pinyin:"dú",meaning:"难道，表反问语气。【古今异义】非「独自/单独」。"},{id:"buwen",term:"不闻之",pinyin:"bù wén zhī",meaning:"没有听到那……之：代词，指下文「翏翏」之声。"},{id:"liuliu",term:"翏翏",pinyin:"liù liù",meaning:"风吹的声音，形容风声高远绵长。叠词，拟声词。"},{id:"shanlin",term:"山林",pinyin:"shān lín",meaning:"山间林木，此处泛指自然中的山林地带。"},{id:"weijia",term:"畏佳",pinyin:"wēi jiā",meaning:"高大茂密的样子。畏：通「巍」，高大；佳：美好茂盛。⚠️ 通假字。"},{id:"damubawei",term:"大木百围",pinyin:"dà mù bǎi wéi",meaning:"粗达百围的大树。百围：极言树干粗大，围：两手合抱为一围。"},{id:"qiaoxue",term:"窍穴",pinyin:"qiào xué",meaning:"孔洞、穴口。风吹过这些孔穴发出各种声音，即「地籁」的来源。"},{id:"sijī",term:"似笄",pinyin:"sì jī",meaning:"像发簪一样细长的孔。笄：古代束发的簪子，形细长。"},{id:"sijuan",term:"似圈",pinyin:"sì juān",meaning:"像圆圈一样的孔。圈：圆形的环。"},{id:"sijiu",term:"似臼",pinyin:"sì jiù",meaning:"像石臼一样深凹的穴。臼：舂米用的石器，中间深凹。"},{id:"siwa",term:"似洼者",pinyin:"sì wā zhě",meaning:"像浅坑一样的孔穴。洼：低凹处，较浅。"},{id:"siwu",term:"似污者",pinyin:"sì wū zhě",meaning:"像积水坑一样的孔穴。污：低洼积水处。"},{id:"jizhe",term:"激者",pinyin:"jī zhě",meaning:"发出湍急冲激声的孔穴。激：水流冲激，形容声音急促。"},{id:"xiaozhe",term:"謞者",pinyin:"xiāo zhě",meaning:"发出尖锐呼啸声的孔穴。謞：声音尖利高亢。"},{id:"chizhe",term:"叱者",pinyin:"chì zhě",meaning:"发出呵斥怒喝声的孔穴。叱：大声呵斥。"},{id:"xizhe",term:"吸者",pinyin:"xī zhě",meaning:"发出吸气细声的孔穴。吸：细微吸入声，与「叱」形成大小对比。"},{id:"jiaozhe",term:"叫者",pinyin:"jiào zhě",meaning:"发出高声叫喊声的孔穴。叫：高亢鸣叫。"},{id:"haozhe",term:"譹者",pinyin:"háo zhě",meaning:"发出悲号哭泣声的孔穴。譹：悲哀号哭之声。"},{id:"yaozhe",term:"宎者",pinyin:"yǎo zhě",meaning:"发出深远幽鸣声的孔穴。宎：深远空旷之声。"},{id:"yaozhe2",term:"咬者",pinyin:"jiāo zhě",meaning:"发出细碎切切声的孔穴。咬：读 jiāo，细碎轻微之声。⚠️ 非「咬」(yǎo)，注意字音。"},{id:"qianzhe",term:"前者",pinyin:"qián zhě",meaning:"前面的风声、领头的声音。"},{id:"chang",term:"唱",pinyin:"chàng",meaning:"领唱，发出先导之声。【古今异义】古义为「倡导/领先发声」，非现代「唱歌」。"},{id:"yu_sound",term:"于",pinyin:"yú",meaning:"风声呜呜的拟声词。⚠️ 此处非介词「于」，是模拟风声的象声字。"},{id:"er_sui",term:"而",pinyin:"ér",meaning:"连词，表承接，然后。"},{id:"suizhe",term:"随者",pinyin:"suí zhě",meaning:"跟随在后的风声。与「前者」对举。"},{id:"changyong",term:"唱喁",pinyin:"chàng yóng",meaning:"应和之声。喁：跟随应和的声音，与前文「于」（领声）相对。"},{id:"lingfeng",term:"泠风则小和",pinyin:"líng fēng zé xiǎo hè",meaning:"小风则孔穴发出细小的应和声。泠风：小风、微风；和：应和，读 hè。"},{id:"piaofeng",term:"飘风则大和",pinyin:"piāo fēng zé dà hè",meaning:"大风则孔穴发出宏大的应和声。飘风：疾风、大风；与「泠风」形成对比。"},{id:"lifeng",term:"厉风",pinyin:"lì fēng",meaning:"猛烈的风，暴风。厉：猛烈、强劲。"},{id:"ji_stop",term:"济",pinyin:"jì",meaning:"止息、停止。【古今异义】此处非「渡河/救济」，而是「止」义。"},{id:"wanqiaoweixu",term:"众窍为虚",pinyin:"zhòng qiào wéi xū",meaning:"万千孔穴归于寂静空虚。为虚：变为空寂，风止则声息。"},{id:"dubujianzhi",term:"独不见之",pinyin:"dú bù jiàn zhī",meaning:"难道没有看到那……独：难道，表反问；之：代词，指下文树木摇动之貌。"},{id:"diaodiao",term:"调调之刁刁",pinyin:"tiáo tiáo zhī diāo diāo",meaning:"树枝摇曳、树叶颤动的样子。调调：枝条大幅摇摆；刁刁：叶片细碎颤动。两词叠用，描绘风过树动之态。"},{id:"dilai2",term:"地籁",pinyin:"dì lài",meaning:"大地的声音。子游在此作出定义：地籁就是众窍（孔穴）发出的声音。"},{id:"zhongqiao",term:"众窍",pinyin:"zhòng qiào",meaning:"万千孔穴。众：众多；窍：孔洞。"},{id:"shiye",term:"是已",pinyin:"shì yǐ",meaning:"就是这个了，就是如此。是：指示代词；已：语气词，表确认，相当于「了/矣」。"},{id:"renlai2",term:"人籁",pinyin:"rén lài",meaning:"人为发出的声音。子游在此作出定义：人籁就是比竹（排箫）发出的声音。"},{id:"bizhu",term:"比竹",pinyin:"bǐ zhú",meaning:"排箫，将竹管并排而成的乐器。比：并排、并列；竹：竹管。"},{id:"tianlai2",term:"天籁",pinyin:"tiān lài",meaning:"天地自然本真之声。子游问天籁，子綦以「吹万不同，咸其自取」作答——天籁无形无主，万物各自发声，无所依待。"},{id:"chuiwan",term:"吹万不同",pinyin:"chuī wàn bù tóng",meaning:"（风）吹动万物，各自发出不同的声音。吹万：吹动万物；不同：声音各异。"},{id:"shiqiziji",term:"使其自己也",pinyin:"shǐ qí zì jǐ yě",meaning:"让它们各自停止。使：让；自己：自行停止，己通「止」。⚠️ 非现代「自己」（自身）义。【通假字】"},{id:"xian",term:"咸",pinyin:"xián",meaning:"都、全都。副词。【古今异义】非「咸味」。"},{id:"ziqu",term:"其自取",pinyin:"qí zì qǔ",meaning:"它们各自取得（自己的声音）。自取：自己选取，强调声音出于万物本身，无外力主宰。"},{id:"nuzhequishei",term:"怒者其谁邪",pinyin:"nù zhě qí shuí yé",meaning:"那个使它们鼓动发声的究竟是谁呢？怒：鼓动、激发；其谁：究竟是谁，反问。暗示天籁无主宰，万物自然而然，即「无待」的最高境界。"}],d=[{id:"xindou_s1",label:"大知闲闲……日以心斗",sentences:[[{text:"大知闲闲",glossary:"dazhi_xianxian"},"，",{text:"小知间间",glossary:"xiaozhi_jianjian"},"。"],[{text:"大言炎炎",glossary:"dayan_yanyan"},"，",{text:"小言詹詹",glossary:"xiaoyan_zhanzhan"},"。"],[{text:"其寐也魂交",glossary:"mei_hunjiao"},"，",{text:"其觉也形开",glossary:"jue_xingkai"},"。"],[{text:"与接为构",glossary:"yujiegou"},"，",{text:"日以心斗",glossary:"rixindou"},"。"]]},{id:"xindou_s2",label:"缦者、窖者、密者……近死之心，莫使复阳也",sentences:[[{text:"缦者",glossary:"manzhe"},"、",{text:"窖者",glossary:"jiaozhe_xin"},"、",{text:"密者",glossary:"mizhe"},"。"],[{text:"小恐惴惴",glossary:"xiaokong_zhuizui"},"，",{text:"大恐缦缦",glossary:"dakong_manman"},"。"],["其",{text:"发",glossary:"fa_ji"},"若",{text:"机栝",glossary:"jigua"},"，其",{text:"司",glossary:"si_zhifa"},{text:"是非",glossary:"shifei"},{text:"之谓也",glossary:"zhiwei"},"；"],["其",{text:"留",glossary:"liu_zhu"},"如",{text:"诅盟",glossary:"zumeng"},"，其",{text:"守胜",glossary:"shoushen"},{text:"之谓也",glossary:"zhiwei"},"；"],["其",{text:"杀",glossary:"sha_xiao"},"如秋冬，",{text:"以",glossary:"yi_yan"},{text:"言",glossary:"yan_shuoming"},"其",{text:"日消",glossary:"rixiao"},"也；"],["其",{text:"溺",glossary:"ni_chen"},{text:"之所为之",glossary:"suoweizhi"},"，不可",{text:"使复之",glossary:"shufuzhi"},"也；"],["其",{text:"厌",glossary:"yan_bi"},"也如",{text:"缄",glossary:"jian_feng"},"，以言其",{text:"老洫",glossary:"laoxu"},"也；"],[{text:"近死之心",glossary:"jinsi_zixin"},"，",{text:"莫",glossary:"mo_wu"},{text:"使",glossary:"shi_ling"},{text:"复阳",glossary:"fuyang"},"也。"]]},{id:"xindou_s3",label:"喜怒哀乐……其所由以生乎",sentences:[["喜怒哀乐，",{text:"虑叹变蜇",glossary:"lvtan_bianzhe"},"，",{text:"姚佚启态",glossary:"yaoyi_qitai"},"——"],[{text:"乐出虚",glossary:"le_chuxu"},"，",{text:"蒸成菌",glossary:"zheng_chengjun"},"。"],["日夜",{text:"相代",glossary:"xiangdai"},"乎",{text:"前",glossary:"qian_mianqian"},"，而",{text:"莫知",glossary:"mozhi"},{text:"其所萌",glossary:"suomeng"},"。"],[{text:"已乎",glossary:"yihu"},"，",{text:"已乎",glossary:"yihu"},"！"],[{text:"旦暮",glossary:"danmu"},{text:"得此",glossary:"deci"},"，",{text:"其所由",glossary:"suoyou"},{text:"以生乎",glossary:"yishenghu"},"！"]]},{id:"zhenzai_s1",label:"非彼无我……可行己信",sentences:[[{text:"非彼无我",glossary:"feibiwuwo"},"，",{text:"非我无所取",glossary:"feiwowusuoqu"},"。"],[{text:"是亦近矣",glossary:"shiyijin"},"，而不知",{text:"其",glossary:"qi_zhishi"},{text:"所为使",glossary:"suoweishi"},"。"],["若有",{text:"真宰",glossary:"zhenzai"},"，而",{text:"特",glossary:"te_dan"},"不得其",{text:"眹",glossary:"zhen_ji"},"。"],[{text:"可行己信",glossary:"kexing_jixin"},"，而不见其形，有情而无形。"]]},{id:"zhenzai_s2",label:"百骸、九窍、六藏……其有真君存焉",sentences:[[{text:"百骸",glossary:"baihei"},"、",{text:"九窍",glossary:"jiuqiao"},"、",{text:"六藏",glossary:"liuzang"},"、",{text:"赅而存焉",glossary:"gaierzunyan"},"，"],["吾",{text:"谁与为亲",glossary:"shuiyuweiqin"},"？"],[{text:"汝皆说之乎",glossary:"rujieyuezhi"},"？",{text:"其有私焉",glossary:"qiyousiyan"},"？"],[{text:"如是",glossary:"rushi"},{text:"皆",glossary:"jie_dou"},{text:"有为臣妾乎",glossary:"weichenqie"},"？其臣妾不足以",{text:"相治",glossary:"xiangzhi"},"乎？"],[{text:"其递相为君臣乎",glossary:"dixiang_junchen"},"？其有",{text:"真君",glossary:"zhenjun"},"存焉！"]]},{id:"zhenzai_s3",label:"如求得其情……不亦悲乎",sentences:[["如",{text:"求",glossary:"qiu_xunqiu"},"得其",{text:"情",glossary:"qing_shiqing"},"与不得，",{text:"无",glossary:"wu_bu"},{text:"益",glossary:"yi_zengjia"},{text:"损",glossary:"sun_jianshao"},"乎其",{text:"真",glossary:"zhen_benti"},"。"],["一",{text:"受",glossary:"shou_cheng"},"其成形，不",{text:"亡",glossary:"wang_gai"},{text:"以",glossary:"yi_lai"},{text:"待",glossary:"dai_dengdai"},{text:"尽",glossary:"jin_siqu"},"。"],["与物",{text:"相刃相靡",glossary:"xiangren_xiangmi"},"，其行",{text:"尽如驰",glossary:"jinruchi"},"而莫之能止，不亦悲乎！"]]},{id:"zhenzai_s4",label:"终身役役……其我独芒，而人亦有不芒者乎",sentences:[[{text:"终身",glossary:"zhongshen"},{text:"役役",glossary:"yiyi_laoku"},"而不见其",{text:"成功",glossary:"chenggong_gu"},"，"],[{text:"苶然疲役",glossary:"nieran_piyi"},"而不知",{text:"其所归",glossary:"suogui"},"，可不",{text:"哀",glossary:"ai_beishang"},"邪！"],["人",{text:"谓之不死",glossary:"weizhi_busi"},"，",{text:"奚益",glossary:"xiyi"},"！"],["其形",{text:"化",glossary:"hua_bianhua"},"，其",{text:"心",glossary:"xin_suizhi"},{text:"与之然",glossary:"yuzhiran"},"，可不谓",{text:"大哀",glossary:"daai"},"乎？"],[{text:"人之生也",glossary:"renzhisheng"},"，",{text:"固若是芒乎",glossary:"gurushimang"},"？"],["其",{text:"我独芒",glossary:"wodumang"},"，而人亦有",{text:"不芒者",glossary:"bumangzhe"},"乎？"]]}],u=[{id:"dazhi_xianxian",term:"大知闲闲",pinyin:"dà zhī xián xián",meaning:"大智慧者广博从容。知通「智」；闲闲：广博宽裕、悠然自得的样子。【通假字】"},{id:"xiaozhi_jianjian",term:"小知间间",pinyin:"xiǎo zhī jiàn jiàn",meaning:"小聪明者斤斤计较。间间：细察分辨、锱铢必较的样子。与「闲闲」对举。"},{id:"dayan_yanyan",term:"大言炎炎",pinyin:"dà yán yán yán",meaning:"大言论气势磅礴、光焰炽盛。炎炎：火势旺盛，形容气势宏大。"},{id:"xiaoyan_zhanzhan",term:"小言詹詹",pinyin:"xiǎo yán zhān zhān",meaning:"小言论琐碎啰嗦。詹詹：多言絮叨的样子。与「炎炎」对举。"},{id:"mei_hunjiao",term:"其寐也魂交",pinyin:"qí mèi yě hún jiāo",meaning:"睡着时魂魄纷乱交扰。寐：睡着；魂交：魂魄交缠，指梦中心神不宁。"},{id:"jue_xingkai",term:"其觉也形开",pinyin:"qí jué yě xíng kāi",meaning:"醒来时形体与外物接触张开。觉：醒来；形开：形体向外界敞开，与万物接触。"},{id:"yujiegou",term:"与接为构",pinyin:"yǔ jiē wéi gòu",meaning:"与外物接触便产生纠缠牵绊。接：接触外物；构：构成纠葛、缠绕。"},{id:"rixindou",term:"日以心斗",pinyin:"rì yǐ xīn dòu",meaning:"每天都用心机与外物争斗。日：每天，名词作状语；以心斗：用心机争斗。"},{id:"manzhe",term:"缦者",pinyin:"màn zhě",meaning:"迟缓拖沓的心态。缦：缓慢、散漫，形容心机迟钝绵延。"},{id:"jiaozhe_xin",term:"窖者",pinyin:"jiào zhě",meaning:"深藏阴险的心态。窖：地窖，深藏不露，形容心机深沉隐秘。"},{id:"mizhe",term:"密者",pinyin:"mì zhě",meaning:"细密周到的心态。密：细密严谨，形容心机缜密。三者合描世人心斗的三种形态。"},{id:"xiaokong_zhuizui",term:"小恐惴惴",pinyin:"xiǎo kǒng zhuì zhuì",meaning:"小恐惧时惶惶不安。惴惴：恐惧忧虑的样子。"},{id:"dakong_manman",term:"大恐缦缦",pinyin:"dà kǒng màn màn",meaning:"大恐惧时茫然失措。缦缦：茫然无措、心神涣散的样子。与「惴惴」对举，小恐紧张，大恐反而麻木。"},{id:"fa_ji",term:"发",pinyin:"fā",meaning:"发动、触发。指心机的触发，如弩机扣动。"},{id:"jigua",term:"机栝",pinyin:"jī guā",meaning:"弩机的扳机。机：弩弓发射装置；栝：箭尾缺口。比喻心机触发之迅猛。"},{id:"si_zhifa",term:"司",pinyin:"sī",meaning:"主管、掌控。【古今异义】非现代「司机/公司」义，此处为动词「主持、执掌」。"},{id:"shifei",term:"是非",pinyin:"shì fēi",meaning:"对与错的判断。此处指心机专门执掌是非判断，带有执念与偏见。"},{id:"zhiwei",term:"之谓也",pinyin:"zhī wèi yě",meaning:"说的就是这个意思。固定句式「……之谓也」，表解释说明。"},{id:"liu_zhu",term:"留",pinyin:"liú",meaning:"执守、滞留。指心机执守某一立场不肯放弃，如诅盟般牢固。"},{id:"zumeng",term:"诅盟",pinyin:"zǔ méng",meaning:"诅咒盟誓。诅：诅咒；盟：盟誓。比喻心机执守立场之顽固，如同盟誓不可更改。"},{id:"shoushen",term:"守胜",pinyin:"shǒu shèng",meaning:"执守胜利、坚持己见。指不肯认输、死守优势的心理。"},{id:"sha_xiao",term:"杀",pinyin:"shài",meaning:"衰减、消退。【古今异义】此处读 shài，非「杀死」，指生机逐渐衰减如秋冬凋零。"},{id:"yi_yan",term:"以",pinyin:"yǐ",meaning:"用来，介词。以言：用来说明、表示。"},{id:"yan_shuoming",term:"言",pinyin:"yán",meaning:"说明、表达。此处为动词，以言其日消：用来说明它每天都在消减。"},{id:"rixiao",term:"日消",pinyin:"rì xiāo",meaning:"每天消减。日：每天，名词作状语；消：消退减少。"},{id:"ni_chen",term:"溺",pinyin:"nì",meaning:"沉溺、陷入。指心神深陷某种执念或欲望无法自拔。"},{id:"suoweizhi",term:"之所为之",pinyin:"zhī suǒ wéi zhī",meaning:"它所做的那些事。之所为：所做的事情；之：代词，指沉溺的状态。"},{id:"shufuzhi",term:"使复之",pinyin:"shǐ fù zhī",meaning:"使它回复（原来的状态）。复：回复、恢复；之：代词，指未沉溺前的状态。"},{id:"yan_bi",term:"厌",pinyin:"yān",meaning:"封闭、压抑。【古今异义】此处读 yān，非「厌倦」，指心灵被封闭压抑如同封口。"},{id:"jian_feng",term:"缄",pinyin:"jiān",meaning:"封口、封缄。缄：捆扎封口，比喻心灵被封闭，不再开放。"},{id:"laoxu",term:"老洫",pinyin:"lǎo xù",meaning:"衰老枯竭。洫：沟渠干涸，引申为枯竭。形容心灵随年老而日益枯竭。"},{id:"jinsi_zixin",term:"近死之心",pinyin:"jìn sǐ zhī xīn",meaning:"接近死亡的心灵状态。形容心灵已极度枯竭，几近死灭。"},{id:"mo_wu",term:"莫",pinyin:"mò",meaning:"没有什么能……否定性无定代词，表示没有任何事物或力量。"},{id:"shi_ling",term:"使",pinyin:"shǐ",meaning:"使得、让。兼语式动词。"},{id:"fuyang",term:"复阳",pinyin:"fù yáng",meaning:"重新恢复生机。阳：阳气、生机；复阳：使阳气回复，指重新焕发活力。"},{id:"lvtan_bianzhe",term:"虑叹变蜇",pinyin:"lǜ tàn biàn zhé",meaning:"忧虑、叹息、变化、惊蛰（蛰伏）。蜇：通「蛰」，蛰伏潜藏。四种情绪状态的并列。"},{id:"yaoyi_qitai",term:"姚佚启态",pinyin:"yáo yì qǐ tài",meaning:"放纵、轻佚、兴奋、作态。姚：放纵；佚：轻佚放荡；启：开启兴奋；态：作态造作。四种情绪状态的并列。"},{id:"le_chuxu",term:"乐出虚",pinyin:"yuè chū xū",meaning:"音乐从空虚中产生。比喻情绪与心灵状态皆从虚无中生发，无固定根源。"},{id:"zheng_chengjun",term:"蒸成菌",pinyin:"zhēng chéng jūn",meaning:"湿气蒸腾而生出菌类。比喻情绪在无意识中自然滋生，无法追溯根源。"},{id:"xiangdai",term:"相代",pinyin:"xiāng dài",meaning:"交替更替。日夜相代：日夜交替出现在眼前，指情绪不断轮替。"},{id:"qian_mianqian",term:"前",pinyin:"qián",meaning:"面前、眼前。乎前：在眼前，乎：介词，相当于「于」。"},{id:"mozhi",term:"莫知",pinyin:"mò zhī",meaning:"没有人知道。莫：无定代词，没有人；知：知晓。"},{id:"suomeng",term:"其所萌",pinyin:"qí suǒ méng",meaning:"它们萌生的根源。萌：萌发、起源；所萌：萌生之处。"},{id:"yihu",term:"已乎",pinyin:"yǐ hū",meaning:"算了吧！罢了！已：停止、算了；乎：感叹语气词。表示无奈感叹，重复两次加强语气。"},{id:"danmu",term:"旦暮",pinyin:"dàn mù",meaning:"早晨与傍晚，泛指每天、终日。"},{id:"deci",term:"得此",pinyin:"dé cǐ",meaning:"经历这些（情绪起伏）。得：经历、遭遇；此：指上文种种情绪。"},{id:"suoyou",term:"其所由",pinyin:"qí suǒ yóu",meaning:"它们由以产生的根源。所由：所从来的原因、根源。"},{id:"yishenghu",term:"以生乎",pinyin:"yǐ shēng hū",meaning:"赖以生存的吗？以生：凭借这些而生存；乎：疑问语气词。全句反问：难道这就是人赖以生存的根本？"},{id:"feibiwuwo",term:"非彼无我",pinyin:"fēi bǐ wú wǒ",meaning:"没有彼（对立面）就没有我。彼：对立的他者；我：自我。庄子相对论的核心：自我依赖对立面而存在。"},{id:"feiwowusuoqu",term:"非我无所取",pinyin:"fēi wǒ wú suǒ qǔ",meaning:"没有我，彼也无从显现。所取：所能呈现、所能作用的对象。彼我相互依存。"},{id:"shiyijin",term:"是亦近矣",pinyin:"shì yì jìn yǐ",meaning:"这（彼我相依）已经接近真相了。是：这个道理；近：接近真理；矣：语气词。"},{id:"qi_zhishi",term:"其",pinyin:"qí",meaning:"却、但是。转折副词，表示话锋一转。"},{id:"suoweishi",term:"所为使",pinyin:"suǒ wéi shǐ",meaning:"驱使它们（彼我）运作的那个东西。为使：驱使、主宰；所为使：被什么所驱使，指背后的主宰者。"},{id:"zhenzai",term:"真宰",pinyin:"zhēn zǎi",meaning:"真正的主宰者。宰：主宰；真宰：万物背后真正的支配力量。庄子认为它存在，但无法找到其迹象。"},{id:"te_dan",term:"特",pinyin:"tè",meaning:"只是、仅仅。副词，表示限定。【古今异义】非「特别/特殊」。"},{id:"zhen_ji",term:"眹",pinyin:"zhèn",meaning:"迹象、征兆。眹：细微的痕迹或迹象。不得其眹：找不到它的任何迹象。"},{id:"kexing_jixin",term:"可行己信",pinyin:"kě xíng jǐ xìn",meaning:"其作用可以得到验证。可行：可以运行、发挥作用；己信：已经可以确信。指真宰的存在可从效果上感知，却无法见其形体。"},{id:"baihei",term:"百骸",pinyin:"bǎi hái",meaning:"全身所有骨骼，泛指整个形体。骸：骨骼；百：极言其多。"},{id:"jiuqiao",term:"九窍",pinyin:"jiǔ qiào",meaning:"人体九个孔窍：眼二、耳二、鼻二、口、前阴、后阴。"},{id:"liuzang",term:"六藏",pinyin:"liù zàng",meaning:"六脏。藏通「脏」，指心、肝、脾、肺、肾及心包（或说法不一）。【通假字】"},{id:"gaierzunyan",term:"赅而存焉",pinyin:"gāi ér cún yān",meaning:"全都具备地存在于此。赅：完备、齐全；存焉：存在于此。"},{id:"shuiyuweiqin",term:"谁与为亲",pinyin:"shuí yǔ wéi qīn",meaning:"我与哪个最亲近？与：介词，跟；为亲：作为亲近的对象。反问：身体各部分都有，究竟哪个才是「我」？"},{id:"rujieyuezhi",term:"汝皆说之乎",pinyin:"rǔ jiē yuè zhī hū",meaning:"你（我）都喜爱它们吗？说通「悦」，喜爱；皆：都。【通假字】"},{id:"qiyousiyan",term:"其有私焉",pinyin:"qí yǒu sī yān",meaning:"还是有所偏爱？其：还是，表选择；私：偏私、偏爱某一部分。"},{id:"rushi",term:"如是",pinyin:"rú shì",meaning:"如此、这样。指上文百骸九窍六藏并存的状态。"},{id:"jie_dou",term:"皆",pinyin:"jiē",meaning:"都、全部。副词。"},{id:"weichenqie",term:"有为臣妾乎",pinyin:"yǒu wéi chén qiè hū",meaning:"都作为臣妾（被支配者）吗？臣妾：臣子与妾侍，指被支配、服从的角色。"},{id:"xiangzhi",term:"相治",pinyin:"xiāng zhì",meaning:"互相管治、相互统辖。指百骸九窍六藏之间能否互相管理。"},{id:"dixiang_junchen",term:"其递相为君臣乎",pinyin:"qí dì xiāng wéi jūn chén hū",meaning:"还是轮流互为君臣？递相：轮流、交替；君臣：主从关系。反问：没有固定主宰，各部分轮流主导？"},{id:"zhenjun",term:"真君",pinyin:"zhēn jūn",meaning:"真正的君主、真正的主宰。与「真宰」呼应，指身体与生命中真正的支配者，其存在可感而不可见。"},{id:"qiu_xunqiu",term:"求",pinyin:"qiú",meaning:"寻求、探求。指寻求真君的实情。"},{id:"qing_shiqing",term:"情",pinyin:"qíng",meaning:"实情、真相。【古今异义】非「情感」，此处指真君的实际状况与本质。"},{id:"wu_bu",term:"无",pinyin:"wú",meaning:"不会、没有。副词，表否定。"},{id:"yi_zengjia",term:"益",pinyin:"yì",meaning:"增益、增加。与「损」对举。"},{id:"sun_jianshao",term:"损",pinyin:"sǔn",meaning:"减损、减少。与「益」对举。无益损：既不增加也不减少。"},{id:"zhen_benti",term:"真",pinyin:"zhēn",meaning:"本真、真实本体。指真君的本质不因人的认知与否而改变。"},{id:"shou_cheng",term:"受",pinyin:"shòu",meaning:"承受、接受。一受其成形：一旦接受了这个已成的形体。"},{id:"wang_gai",term:"亡",pinyin:"wáng",meaning:"失去、消亡。不亡：不消失，指形体一旦形成便不消失，只能等待耗尽。"},{id:"yi_lai",term:"以",pinyin:"yǐ",meaning:"来、用以。连词，表目的。"},{id:"dai_dengdai",term:"待",pinyin:"dài",meaning:"等待。待尽：等待生命耗尽终结。"},{id:"jin_siqu",term:"尽",pinyin:"jìn",meaning:"耗尽、终结。指生命的终结。"},{id:"xiangren_xiangmi",term:"相刃相靡",pinyin:"xiāng rèn xiāng mí",meaning:"互相摩擦碰撞、互相消磨。刃：刀刃相交，指碰撞冲突；靡：磨损消靡。形容人与外物不断摩擦消耗。"},{id:"jinruchi",term:"其行尽如驰",pinyin:"qí xíng jìn rú chí",meaning:"生命的流逝如同奔驰一样停不下来。行尽：走向终结；如驰：像奔马一样飞速。"},{id:"zhongshen",term:"终身",pinyin:"zhōng shēn",meaning:"一辈子、终其一生。"},{id:"yiyi_laoku",term:"役役",pinyin:"yì yì",meaning:"劳苦奔波、不停劳役的样子。叠词，形容终身辛苦劳作。"},{id:"chenggong_gu",term:"成功",pinyin:"chéng gōng",meaning:"完成功业、有所成就。【古今异义】此处偏重「功业的完成」，非现代「成功」的泛义。"},{id:"nieran_piyi",term:"苶然疲役",pinyin:"nié rán pí yì",meaning:"疲惫不堪的样子。苶：疲倦萎靡；疲役：因劳役而疲惫。"},{id:"suogui",term:"其所归",pinyin:"qí suǒ guī",meaning:"它（生命）的归宿。所归：归宿、终点。不知其所归：不知道生命的意义与归宿。"},{id:"ai_beishang",term:"哀",pinyin:"āi",meaning:"悲哀、可悲。此处为形容词，表感叹。"},{id:"weizhi_busi",term:"谓之不死",pinyin:"wèi zhī bù sǐ",meaning:"称他为不死之人。谓：称呼；之：代词，指这样的人。"},{id:"xiyi",term:"奚益",pinyin:"xī yì",meaning:"有什么益处呢？奚：疑问代词，何、什么；益：益处。反问：形虽不死，心已随形化，有何意义？"},{id:"hua_bianhua",term:"化",pinyin:"huà",meaning:"变化、随之改变。其形化：形体随时间变化衰老。"},{id:"xin_suizhi",term:"心",pinyin:"xīn",meaning:"心灵、精神。此处指精神状态随形体衰化而同步衰竭。"},{id:"yuzhiran",term:"与之然",pinyin:"yǔ zhī rán",meaning:"也随之如此（衰化）。与：跟随；之：代词，指形体的变化；然：如此。"},{id:"daai",term:"大哀",pinyin:"dà āi",meaning:"最大的悲哀。形体与心灵同步衰竭，终身劳役而不知归宿，是庄子眼中人生最深的悲剧。"},{id:"renzhisheng",term:"人之生也",pinyin:"rén zhī shēng yě",meaning:"人的一生、人活着。之：助词，取消句子独立性；也：停顿语气词。"},{id:"gurushimang",term:"固若是芒乎",pinyin:"gù ruò shì máng hū",meaning:"本来就是这样迷茫吗？固：本来；若是：像这样；芒：通「茫」，迷茫、蒙昧。【通假字】"},{id:"wodumang",term:"我独芒",pinyin:"wǒ dú máng",meaning:"只有我一个人迷茫。独：唯独、只有；芒：迷茫蒙昧。"},{id:"bumangzhe",term:"不芒者",pinyin:"bù máng zhě",meaning:"不迷茫的人。指能超越执念、达到「吾丧我」境界的觉悟者。与上文「芒」形成对比。"}],p=[{id:"chengxin_s1",label:"夫随其成心而师之……吾独且奈何哉",sentences:[["夫",{text:"随",glossary:"sui_shunzhao"},"其",{text:"成心",glossary:"chengxin"},"而",{text:"师之",glossary:"shizhi"},"，",{text:"独",glossary:"du_shui"},"且无师乎？"],[{text:"奚",glossary:"xi_he"},"必知",{text:"代",glossary:"dai_gengti"},"而",{text:"自取者",glossary:"ziqu_zhe"},{text:"有之",glossary:"youzhi"},"？"],[{text:"愚者",glossary:"yuzhe"},{text:"与有焉",glossary:"youyanyan"},"！"],["未成乎心而有",{text:"是非",glossary:"shifei_chengxin"},"，是今日",{text:"适越",glossary:"shiyue"},"而",{text:"昔至",glossary:"xizhi_dao"},"也。"],["是",{text:"以无有为有",glossary:"wuyouweiyou"},"。无有为有，虽有",{text:"神禹",glossary:"shenyu"},"且不能知，吾",{text:"独",glossary:"du_shui"},"且",{text:"奈何哉",glossary:"naihe"},"！"]]},{id:"shifei_s1",label:"夫言非吹也……莫若以明",sentences:[["夫言",{text:"非吹",glossary:"feichui"},"也，",{text:"言者有言",glossary:"yanzhe_youyan"},"。"],["其所言者",{text:"特未定也",glossary:"teweiding"},"。"],[{text:"果",glossary:"guo_daodi"},"有言邪？其",{text:"未尝",glossary:"weichang"},"有言邪？"],["其以为",{text:"异",glossary:"yi_butong"},"于",{text:"鷇音",glossary:"kouyin"},"，亦有",{text:"辩",glossary:"bian_qubie"},"乎？其无辩乎？"],[{text:"道",glossary:"dao_benti"},{text:"恶乎",glossary:"ewuhu"},{text:"隐",glossary:"yin_yinbi"},"而有",{text:"真伪",glossary:"zhenweiyi"},"？"],["言恶乎隐而有",{text:"是非",glossary:"shifei_chengxin"},"？"],["道恶乎",{text:"往而不存",glossary:"wangbucun"},"？言恶乎",{text:"存而不可",glossary:"cunbuke"},"？"],["道隐于",{text:"小成",glossary:"xiaocheng"},"，言隐于",{text:"荣华",glossary:"ronghua_gu"},"。"],["故有",{text:"儒墨",glossary:"rumu"},"之是非，",{text:"以是其所非",glossary:"yishi_suofei"},"而",{text:"非其所是",glossary:"fei_suoshi"},"。"],[{text:"欲",glossary:"yu_ruoyao"},"是其所非而非其所是，则",{text:"莫若以明",glossary:"moruoyiming"},"。"]]},{id:"daoshu_s1",label:"物无非彼……亦因是也",sentences:[["物无非彼，物无非是。自彼则不见，自",{text:"知",glossary:"zhi_ziji"},"则知之。"],["故曰：彼出于是，是亦因彼。",{text:"彼是方生之说也",glossary:"bifang_shengshuo"},"。"],["虽然，方生方死，方死方生；方可方不可，方不可方可；",{text:"因是因非",glossary:"yinshi_yinfei"},"，因非因是。"],["是以圣人不由而",{text:"照之于天",glossary:"zhaozhiyutian"},"，",{text:"亦因是也",glossary:"yiyinshi"},"。"]]},{id:"daoshu_s2",label:"是亦彼也……故曰莫若以明",sentences:[["是亦彼也，彼亦是也。彼亦一是非，此亦一是非，",{text:"果",glossary:"guo_daodi"},"且有彼是乎哉？果且无彼是乎哉？"],[{text:"彼是莫得其偶",glossary:"bishi_modeou"},"，谓之",{text:"道枢",glossary:"daoshu"},"。"],[{text:"枢始得其环中",glossary:"shu_huanzhong"},"，以应无穷。"],["是亦一无穷，非亦一无穷也。故曰：",{text:"莫若以明",glossary:"moruoyiming"},"。"]]},{id:"daoshu_s3",label:"以指喻指之非指……万物一马也",sentences:[["以",{text:"指",glossary:"zhi_gongming"},{text:"喻",glossary:"yu_biyu"},{text:"指之非指",glossary:"zhi_fei_zhi"},"，不若以非指喻指之非指也；"],["以马喻马之非马，不若以非马喻马之非马也。"],[{text:"天地一指也",glossary:"tiandi_yizhi"},"，",{text:"万物一马也",glossary:"wanwu_yima"},"。"]]},{id:"daoshu_s4",label:"可乎可……道通为一",sentences:[[{text:"可乎可",glossary:"kehuke"},"，",{text:"不可乎不可",glossary:"bukehubuke"},"。"],[{text:"道行之而成",glossary:"dao_xingcheng"},"，",{text:"物谓之而然",glossary:"wu_weizhiran"},"。"],[{text:"恶乎然",glossary:"ewuhu_ran"},"？",{text:"然于然",glossary:"ran_yuran"},"。恶乎不然？不然于不然。"],[{text:"物",glossary:"wu_wanwu"},{text:"固",glossary:"gu_benlai"},{text:"有所然",glossary:"yousuoran"},"，物固",{text:"有所可",glossary:"yousuoke"},"。"],[{text:"无物不然",glossary:"wuwu_buran"},"，",{text:"无物不可",glossary:"wuwu_buke"},"。"],["故为是",{text:"举莛与楹",glossary:"ju_tingyying"},"，",{text:"厉与西施",glossary:"li_xishi"},"，",{text:"恢诡谲怪",glossary:"huigui_jueguai"},"，",{text:"道通为一",glossary:"dao_tongweyi"},"。"]]}],x=[{id:"sui_shunzhao",term:"随",pinyin:"suí",meaning:"顺从、依照。随其成心：顺着自己已有的主观成见。"},{id:"chengxin",term:"成心",pinyin:"chéng xīn",meaning:"已形成的主观成见、固有偏见。成：已成定型；心：主观判断。庄子认为人人皆有成心，以成心为师则是非无定。"},{id:"shizhi",term:"师之",pinyin:"shī zhī",meaning:"以它为师、奉它为准则。师：名词活用为动词，以……为师。"},{id:"du_shui",term:"独",pinyin:"dú",meaning:"谁、哪一个。【古今异义】此处非「独自」，而是疑问代词「谁」。谁独且无师：谁没有（成心之）师？"},{id:"xi_he",term:"奚",pinyin:"xī",meaning:"何必、为什么。疑问副词。【古今异义】非现代常用义，此处表反问。"},{id:"dai_gengti",term:"代",pinyin:"dài",meaning:"更替、变化。知代：懂得事物更替变化的道理。"},{id:"ziqu_zhe",term:"自取者",pinyin:"zì qǔ zhě",meaning:"自己选择（成心）的人。自取：自行取用成心作为判断标准。"},{id:"youzhi",term:"有之",pinyin:"yǒu zhī",meaning:"才有这种情况。之：代词，指以成心为师的情况。"},{id:"yuzhe",term:"愚者",pinyin:"yú zhě",meaning:"愚昧之人。与「知代而自取者」对举，说明无论智愚皆有成心。"},{id:"youyanyan",term:"与有焉",pinyin:"yǔ yǒu yān",meaning:"也都有（成心之师）。与：也、亦；有焉：有之，焉：兼词，于此。"},{id:"shifei_chengxin",term:"是非",pinyin:"shì fēi",meaning:"对与错的判断。庄子认为是非判断皆源于成心，无客观标准。"},{id:"shiyue",term:"适越",pinyin:"shì yuè",meaning:"前往越国。适：前往、去；越：越国，在南方。"},{id:"xizhi_dao",term:"昔至",pinyin:"xī zhì",meaning:"昨天（出发前）就已到达。昔：过去、昨日；至：到达。今日适越而昔至：今天出发却说昨天已到，喻未成心而先有是非之荒谬。"},{id:"wuyouweiyou",term:"以无有为有",pinyin:"yǐ wú yǒu wéi yǒu",meaning:"把没有的当作有。指未成心而先立是非，是把不存在的东西当作存在，是自欺欺人。"},{id:"shenyu",term:"神禹",pinyin:"shén yǔ",meaning:"神明般的大禹。神：神明，形容词修饰禹；禹：治水的圣王。以神禹喻极智之人，强调此事连圣人也无法理解。"},{id:"naihe",term:"奈何哉",pinyin:"nài hé zāi",meaning:"能怎么办呢？奈何：怎么办；哉：感叹语气词。表无奈感叹。"},{id:"feichui",term:"非吹",pinyin:"fēi chuī",meaning:"不是吹风（那样无意义的声音）。言非吹：人说话不同于风吹，是有意义有内容的。与上文地籁（风吹孔穴）区分。"},{id:"yanzhe_youyan",term:"言者有言",pinyin:"yán zhě yǒu yán",meaning:"说话的人是有所言说的（有意图有内容）。强调言语有别于自然之声，有主观意图。"},{id:"teweiding",term:"特未定也",pinyin:"tè wèi dìng yě",meaning:"只是（所言的内容）尚未确定。特：只是、仅仅；未定：没有固定的标准与内容。"},{id:"guo_daodi",term:"果",pinyin:"guǒ",meaning:"究竟、到底。副词，表追问。【古今异义】非「果实/结果」。"},{id:"weichang",term:"未尝",pinyin:"wèi cháng",meaning:"不曾、从未。副词，表示从未发生。"},{id:"yi_butong",term:"异",pinyin:"yì",meaning:"不同、有差异。以为异于鷇音：认为（人言）有别于雏鸟的叫声。"},{id:"kouyin",term:"鷇音",pinyin:"kòu yīn",meaning:"雏鸟的叫声。鷇：待哺的雏鸟；音：声音。比喻无意义的本能之声，用以质疑人言是否真有意义。"},{id:"bian_qubie",term:"辩",pinyin:"biàn",meaning:"区别、分辨。【古今异义】此处非「辩论」，而是「区别/差异」。有辩：有区别；无辩：无区别。"},{id:"dao_benti",term:"道",pinyin:"dào",meaning:"道，天地万物的本体与规律。庄子之「道」无真伪之分，真伪是人为遮蔽的结果。"},{id:"ewuhu",term:"恶乎",pinyin:"wū hū",meaning:"在哪里、怎么会。疑问副词。【古今异义】恶：疑问代词「何/哪里」，非「恶劣」。"},{id:"yin_yinbi",term:"隐",pinyin:"yǐn",meaning:"遮蔽、隐没。道恶乎隐：道在哪里被遮蔽了（才产生真伪之分）？"},{id:"zhenweiyi",term:"真伪",pinyin:"zhēn wěi",meaning:"真实与虚假。庄子认为道本无真伪，真伪之分是人以成心遮蔽道的结果。"},{id:"wangbucun",term:"往而不存",pinyin:"wǎng ér bù cún",meaning:"到哪里去了却不存在。道无处不在，故反问：道往哪里去了而会不存在？"},{id:"cunbuke",term:"存而不可",pinyin:"cún ér bù kě",meaning:"存在着却不被认可。言存而不可：言语存在着，却有不被认可的情况，指是非之争。"},{id:"xiaocheng",term:"小成",pinyin:"xiǎo chéng",meaning:"片面的小成就、局部的成见。道隐于小成：道被局部的偏见所遮蔽。"},{id:"ronghua_gu",term:"荣华",pinyin:"róng huá",meaning:"华丽浮夸的言辞。【古今异义】非「荣耀华贵」，此处指言辞的浮华修饰遮蔽了真意。"},{id:"rumu",term:"儒墨",pinyin:"rú mò",meaning:"儒家与墨家。两大显学，各执是非，互相攻伐，是庄子批判成心是非的典型例证。"},{id:"yishi_suofei",term:"以是其所非",pinyin:"yǐ shì qí suǒ fēi",meaning:"把对方认为错的说成是对的。以是：用「是」来判定；其所非：对方认为错误的。"},{id:"fei_suoshi",term:"非其所是",pinyin:"fēi qí suǒ shì",meaning:"把对方认为对的说成是错的。与「以是其所非」对举，描述儒墨互相攻伐的状态。"},{id:"yu_ruoyao",term:"欲",pinyin:"yù",meaning:"想要、若要。表假设条件。"},{id:"moruoyiming",term:"莫若以明",pinyin:"mò ruò yǐ míng",meaning:"不如用「明」（自然之明）来观照。莫若：不如；以明：以自然的明澈观照，即超越是非对立，用道的视角看待万物。本段两次出现，为核心结论。"},{id:"zhi_gongming",term:"指",pinyin:"zhǐ",meaning:"手指，也指「概念/名称」。此处借「指」喻名称与实体的关系，呼应公孙龙「指物论」。"},{id:"yu_biyu",term:"喻",pinyin:"yù",meaning:"说明、论证。以……喻……：用……来说明……。"},{id:"zhi_fei_zhi",term:"指之非指",pinyin:"zhǐ zhī fēi zhǐ",meaning:"手指（概念）不是（真实的）手指（实体）。名称不等于实体，概念不等于本质。庄子借此说明以名辩名的局限。"},{id:"tiandi_yizhi",term:"天地一指也",pinyin:"tiān dì yī zhǐ yě",meaning:"天地不过是一根手指（一个概念）。从道的视角看，天地万物皆是名称概念，无本质差异。"},{id:"wanwu_yima",term:"万物一马也",pinyin:"wàn wù yī mǎ yě",meaning:"万物不过是一匹马（一个名称）。与「天地一指」并举，强调道通为一，名称差异不影响本质同一。"},{id:"kehuke",term:"可乎可",pinyin:"kě hū kě",meaning:"可以的就让它可以。道对万物的态度：顺其自然，可者任其可。"},{id:"bukehubuke",term:"不可乎不可",pinyin:"bù kě hū bù kě",meaning:"不可以的就让它不可以。与「可乎可」对举，道无强制，顺应万物本然。"},{id:"dao_xingcheng",term:"道行之而成",pinyin:"dào xíng zhī ér chéng",meaning:"道路是走出来的。行之：人走过；成：形成。比喻道不是预设的，是在实践中自然形成的。"},{id:"wu_weizhiran",term:"物谓之而然",pinyin:"wù wèi zhī ér rán",meaning:"事物是被称呼而成其名的。谓之：称呼它；然：如此成立。名称是人赋予的，非事物本有。"},{id:"ewuhu_ran",term:"恶乎然",pinyin:"wū hū rán",meaning:"在哪里是然（可以）的？恶乎：在哪里、怎么会；然：如此、可以。"},{id:"ran_yuran",term:"然于然",pinyin:"rán yú rán",meaning:"在它本然的地方就是然的。于：在；然于然：在它自身本然处便是然。强调然与不然皆出于事物自身，非外力判定。"},{id:"wu_wanwu",term:"物",pinyin:"wù",meaning:"万物、事物。泛指天地间一切存在。"},{id:"gu_benlai",term:"固",pinyin:"gù",meaning:"本来、原本。副词，表示事物本有的状态。【古今异义】非「坚固/固然」。"},{id:"yousuoran",term:"有所然",pinyin:"yǒu suǒ rán",meaning:"有它本然可以的地方。所然：它本然如此的方面。"},{id:"yousuoke",term:"有所可",pinyin:"yǒu suǒ kě",meaning:"有它本然被认可的地方。所可：它本然被肯定的方面。与「有所然」并举。"},{id:"wuwu_buran",term:"无物不然",pinyin:"wú wù bù rán",meaning:"没有事物不是然的。双重否定加强肯定：万物皆有其本然之处。"},{id:"wuwu_buke",term:"无物不可",pinyin:"wú wù bù kě",meaning:"没有事物不是可以的。与「无物不然」并举，强调从道的视角看万物皆有其可。"},{id:"ju_tingyying",term:"举莛与楹",pinyin:"jǔ tíng yǔ yíng",meaning:"举出细草茎与大屋柱作为例子。举：列举；莛：草茎，细小；楹：厅堂大柱，粗大。以大小悬殊之物说明道通为一。"},{id:"li_xishi",term:"厉与西施",pinyin:"lì yǔ xī shī",meaning:"举出丑女厉与美女西施作为例子。厉：丑陋的女子；西施：著名美女。以美丑对立说明道通为一，美丑无绝对。"},{id:"huigui_jueguai",term:"恢诡谲怪",pinyin:"huī guǐ jué guài",meaning:"宏大奇异、诡谲怪诞的种种事物。恢：宏大；诡：奇异；谲：变幻；怪：怪诞。泛指一切看似对立差异悬殊的事物。"},{id:"dao_tongweyi",term:"道通为一",pinyin:"dào tōng wéi yī",meaning:"从道的角度看都贯通为一体。道通：道将万物贯通；为一：归于同一。本段核心结论，呼应「莫若以明」。"},{id:"zhi_ziji",term:"知",pinyin:"zhī",meaning:"自知、从自身出发来认识。自知则知之：从自身视角出发才能认识自身。与「自彼则不见」对举。"},{id:"bifang_shengshuo",term:"彼是方生之说也",pinyin:"bǐ shì fāng shēng zhī shuō yě",meaning:"这就是彼此相互依存而生的说法。方生：相互依存而生；之说：这种学说。指彼我、是非皆相对而生，无独立存在。"},{id:"yinshi_yinfei",term:"因是因非",pinyin:"yīn shì yīn fēi",meaning:"依据「是」又依据「非」。因：依据、顺着；是非相互依存，无绝对的是，也无绝对的非。"},{id:"zhaozhiyutian",term:"照之于天",pinyin:"zhào zhī yú tiān",meaning:"用自然之光来观照（是非）。照：观照、映照；天：自然、天道。不由成心是非，而以天道自然之明观照万物。"},{id:"yiyinshi",term:"亦因是也",pinyin:"yì yīn shì yě",meaning:"也是顺应这个（自然之道）。因是：顺应此道；亦：也，表示圣人之举同样是顺道而为。"},{id:"bishi_modeou",term:"彼是莫得其偶",pinyin:"bǐ shì mò dé qí ǒu",meaning:"彼与是都找不到与之对立的另一面。偶：对立面、配偶（参见第一段「丧其耦」）。超越彼此对立，才能得道枢。"},{id:"daoshu",term:"道枢",pinyin:"dào shū",meaning:"道的枢纽、关键。枢：门轴，转动的核心。道枢即超越是非对立、居于中心的那个关键点。"},{id:"shu_huanzhong",term:"枢始得其环中",pinyin:"shū shǐ dé qí huán zhōng",meaning:"门轴安置在圆环的中心，才能转动自如以应无穷。环中：圆环的中心空处；比喻超越是非对立，居于中道，方能应对无穷变化。"}],z=[{id:"daotong_s1",label:"其分也成也……因是已",sentences:[["其",{text:"分",glossary:"fen_fenlie"},"也，",{text:"成",glossary:"cheng_sheng"},"也；其",{text:"成",glossary:"cheng_sheng"},"也，",{text:"毁",glossary:"hui_huimie"},"也。"],["凡物无成与毁，",{text:"复",glossary:"fu_huigui"},{text:"通为一",glossary:"tongweyi"},"。"],[{text:"唯",glossary:"wei_zhiyou"},{text:"达者",glossary:"dazhe"},"知通为一，为是不用而",{text:"寓",glossary:"yu_jitu"},{text:"诸",glossary:"zhu_yuzhong"},{text:"庸",glossary:"yong_yong"},"。"],[{text:"庸也者",glossary:"yong_yong"},"，用也；用也者，",{text:"通",glossary:"tong_guantong"},"也；通也者，",{text:"得",glossary:"de_dedao"},"也。"],[{text:"适得",glossary:"shide"},"而",{text:"几",glossary:"ji_jin"},"矣。"],[{text:"因是已",glossary:"yinshiyi"},"，已而",{text:"不知其然",glossary:"buzhiqiran"},"，谓之道。"]]},{id:"daotong_s2",label:"劳神明为一……是之谓两行",sentences:[[{text:"劳",glossary:"lao_fei"},{text:"神明",glossary:"shenming"},"为一而不知其",{text:"同",glossary:"tong_xiangtong"},"也，谓之「朝三」。"],["何谓「朝三」？",{text:"狙公赋芧",glossary:"jugong_fushu"},"，曰：「",{text:"朝三而暮四",glossary:"zhaosan_musi"},"。」"],[{text:"众",glossary:"zhong_qunti"},"狙",{text:"皆",glossary:"jie_dou2"},{text:"怒",glossary:"nu_fennu"},"。"],["曰：「",{text:"然则",glossary:"ranze"},"朝四而暮三。」众狙",{text:"皆",glossary:"jie_dou2"},{text:"悦",glossary:"yue_xiyue"},"。"],[{text:"名实未亏",glossary:"mingshi_weikui"},"而喜怒为用，",{text:"亦因是也",glossary:"yiyinshi2"},"。"],["是以圣人",{text:"和之",glossary:"hezhi"},"以是非而",{text:"休",glossary:"xiu_xizhi"},"乎",{text:"天钧",glossary:"tianjun"},"，是之谓",{text:"两行",glossary:"liangxing"},"。"]]},{id:"zhizhi_s1",label:"古之人其知有所至……道之所以亏也",sentences:[["古之人，",{text:"其知有所至矣",glossary:"zhiyousuozhi"},"。",{text:"恶乎至",glossary:"ewuhu_zhi"},"？"],[{text:"有以为",glossary:"youyiwei"},{text:"未始",glossary:"weishi"},{text:"有物者",glossary:"youwuzhe"},"，",{text:"至",glossary:"zhi_zuigao"},"矣，",{text:"尽",glossary:"jin_wuyi"},"矣，不可以",{text:"加",glossary:"jia_chaoguo"},"矣！"],[{text:"其次",glossary:"qici"},"以为有物矣，而未始有",{text:"封",glossary:"feng_jiexian"},"也。"],["其次以为有封焉，而未始有",{text:"是非",glossary:"shifei_zhizhi"},"也。"],["是非之",{text:"彰",glossary:"zhang_xianlu"},"也，道之所以",{text:"亏",glossary:"kui_sunhao"},"也。"]]},{id:"zhizhi_s2",label:"道之所以亏……无成与亏故昭氏之不鼓琴也",sentences:[["道之所以亏，",{text:"爱",glossary:"ai_pianhao"},"之所以",{text:"成",glossary:"cheng_xingcheng"},"。"],[{text:"果",glossary:"guo_jiujing"},{text:"且",glossary:"qie_nandao"},"有成与亏乎哉？果且无成与亏乎哉？"],["有成与亏，故",{text:"昭氏",glossary:"zhaoshi"},"之",{text:"鼓琴",glossary:"guqin"},"也；"],["无成与亏，故昭氏之不鼓琴也。"]]},{id:"zhizhi_s3",label:"昭文之鼓琴也……终身无成",sentences:[["昭文之鼓琴也，",{text:"师旷之枝策也",glossary:"shikuang_zhice"},"，",{text:"惠子之据梧也",glossary:"huizi_juwu"},"，"],[{text:"三子",glossary:"sanzi"},{text:"之",glossary:"zhi_de"},{text:"知几乎",glossary:"zhijhu"},{text:"皆其盛者也",glossary:"jieqishengzhe"},"，故",{text:"载之末年",glossary:"zai_monian"},"。"],[{text:"唯其好之也",glossary:"haozhiye"},{text:"以异于彼",glossary:"yiyubi"},"，其好之也",{text:"欲以明之",glossary:"yuyiming"},"。"],["彼非所明而明之，故以",{text:"坚白之昧终",glossary:"jianbaimeizong"},"。"],["而其子又以",{text:"文之纶终",glossary:"wenzhi_lunzhong"},"，终身无成。"]]},{id:"zhizhi_s4",label:"若是而可谓成乎……此之谓以明",sentences:[["若是而可谓成乎，虽我亦成也；若是而不可谓成乎，物与我无成也。"],["是故",{text:"滑疑之耀",glossary:"huayi_yaoyao"},"，",{text:"圣人之所图",glossary:"shengren_suotu"},"也。"],["为是不用而寓诸庸，此之谓",{text:"以明",glossary:"yiming"},"。"]]}],_=[{id:"fen_fenlie",term:"分",pinyin:"fēn",meaning:"分裂、分开。事物从整体分裂为部分，即「成」的开始。"},{id:"cheng_sheng",term:"成",pinyin:"chéng",meaning:"生成、形成。分裂产生新的个体即为成；但成的同时也是另一面的毁。"},{id:"hui_huimie",term:"毁",pinyin:"huǐ",meaning:"毁灭、消亡。成与毁相互依存，从道的视角看无绝对的成与毁。"},{id:"fu_huigui",term:"复",pinyin:"fù",meaning:"回归、重新。复通为一：重新归于通一之道。"},{id:"tongweyi",term:"通为一",pinyin:"tōng wéi yī",meaning:"贯通归为一体。超越成毁对立，从道的视角看万物本为一体。呼应上段「道通为一」。"},{id:"wei_zhiyou",term:"唯",pinyin:"wéi",meaning:"只有、唯有。副词，表限定。"},{id:"dazhe",term:"达者",pinyin:"dá zhě",meaning:"通达之人，得道者。达：通达、明白；者：代词。与下文「愚者」「众狙」形成对比。"},{id:"yu_jitu",term:"寓",pinyin:"yù",meaning:"寄托、寄寓。寓诸庸：将（道）寄托于日常平庸之用中。"},{id:"zhu_yuzhong",term:"诸",pinyin:"zhū",meaning:"于之，兼词。诸=之+于，寓诸庸=寄托于庸之中。"},{id:"yong_yong",term:"庸",pinyin:"yōng",meaning:"日常平常之用。【古今异义】非「平庸/庸俗」，此处指日常普通的功用。庸也者，用也：平常之用就是功用本身。"},{id:"tong_guantong",term:"通",pinyin:"tōng",meaning:"贯通、通达。用则通：发挥功用便能贯通万物。"},{id:"de_dedao",term:"得",pinyin:"dé",meaning:"得道、获得。通则得：贯通便能得道。庸→用→通→得，四步递进的逻辑链。"},{id:"shide",term:"适得",pinyin:"shì dé",meaning:"恰好得到（道）。适：恰好、正好。"},{id:"ji_jin",term:"几",pinyin:"jī",meaning:"接近、差不多。适得而几：恰好得到便接近（道）了。【古今异义】非「几乎/几个」，此处为「接近」。"},{id:"yinshiyi",term:"因是已",pinyin:"yīn shì yǐ",meaning:"顺应这个（道）就够了。因是：顺应此道；已：止、足够，语气词。"},{id:"buzhiqiran",term:"不知其然",pinyin:"bù zhī qí rán",meaning:"不知道它为什么是这样。已而不知其然：顺应道而行却不知其所以然，这才叫做道。强调道的自然无为。"},{id:"lao_fei",term:"劳",pinyin:"láo",meaning:"劳费、耗费。劳神明：耗费精神智慧。【古今异义】非「劳动」，此处为「耗费」。"},{id:"shenming",term:"神明",pinyin:"shén míng",meaning:"精神智慧。【古今异义】非「神灵」，此处指人的精神与智慧。劳神明为一：耗费精神智慧去追求统一。"},{id:"tong_xiangtong",term:"同",pinyin:"tóng",meaning:"相同、本同。不知其同：不知道万物本来就是相同的（通为一）。"},{id:"jugong_fushu",term:"狙公赋芧",pinyin:"jū gōng fù shù",meaning:"养猴人分发橡实。狙公：养猴人；赋：分发、给予；芧：橡树果实，猴子的食物。"},{id:"zhaosan_musi",term:"朝三而暮四",pinyin:"zhāo sān ér mù sì",meaning:"早上三颗晚上四颗。总量不变（七颗），仅调换顺序，猴子却因此喜怒。比喻名实未变而人因成心是非而喜怒。"},{id:"zhong_qunti",term:"众",pinyin:"zhòng",meaning:"众多、全体。众狙：所有的猴子。"},{id:"jie_dou2",term:"皆",pinyin:"jiē",meaning:"都、全部。副词。"},{id:"nu_fennu",term:"怒",pinyin:"nù",meaning:"愤怒。与下文「悦」对举，说明喜怒皆因成心而起，非因实质变化。"},{id:"ranze",term:"然则",pinyin:"rán zé",meaning:"既然如此，那么。表承接转折的连词。"},{id:"yue_xiyue",term:"悦",pinyin:"yuè",meaning:"高兴、喜悦。与「怒」对举，名实未变而喜怒随之，正是成心作用的体现。"},{id:"mingshi_weikui",term:"名实未亏",pinyin:"míng shí wèi kuī",meaning:"名称与实质都没有损失。名：名称（朝三暮四/朝四暮三）；实：实质（总量七颗）；亏：亏损、减少。"},{id:"yiyinshi2",term:"亦因是也",pinyin:"yì yīn shì yě",meaning:"也是顺应（成心）这个道理。呼应上段「亦因是也」，指喜怒为用皆因成心所致。"},{id:"hezhi",term:"和之",pinyin:"hé zhī",meaning:"调和它（是非）。和：调和、顺应；之：代词，指是非。圣人不执一端，调和是非两端。"},{id:"xiu_xizhi",term:"休",pinyin:"xiū",meaning:"止息、安住。休乎天钧：安住于天然的均衡之中。【古今异义】非「休息」，此处为「止息/安住」。"},{id:"tianjun",term:"天钧",pinyin:"tiān jūn",meaning:"天然的均衡、自然的平衡。钧：陶轮，均衡旋转；天钧：自然运转的均衡状态，无偏无倚。"},{id:"liangxing",term:"两行",pinyin:"liǎng xíng",meaning:"两者并行、是非两端皆得通行。行：通行、运行。圣人不废是非，而使是非两端皆得其所，谓之两行。"},{id:"zhiyousuozhi",term:"其知有所至矣",pinyin:"qí zhī yǒu suǒ zhì yǐ",meaning:"他们的认知达到了某种极致。知：认知、智慧；有所至：有所到达的极点。"},{id:"ewuhu_zhi",term:"恶乎至",pinyin:"wū hū zhì",meaning:"到达了什么程度？恶乎：到哪里、怎样；至：到达。"},{id:"youyiwei",term:"有以为",pinyin:"yǒu yǐ wéi",meaning:"有人认为。有：有人；以为：认为。"},{id:"weishi",term:"未始",pinyin:"wèi shǐ",meaning:"从未、从来不曾。副词，表示从未有过。"},{id:"youwuzhe",term:"有物者",pinyin:"yǒu wù zhě",meaning:"有万物存在这回事。物：万物；者：助词，指代这种状态。未始有物：从来就没有万物的存在（万物皆空）。"},{id:"zhi_zuigao",term:"至",pinyin:"zhì",meaning:"极致、最高。至矣：达到极致了。"},{id:"jin_wuyi",term:"尽",pinyin:"jìn",meaning:"穷尽、无以复加。尽矣：已经穷尽了。"},{id:"jia_chaoguo",term:"加",pinyin:"jiā",meaning:"超过、更进一步。不可以加：不可能再超越了。【古今异义】非「增加」，此处为「超越/更进」。"},{id:"qici",term:"其次",pinyin:"qí cì",meaning:"次一等的、其次的境界。认知三层次：未始有物→有物未始有封→有封未始有是非，层层递降。"},{id:"feng_jiexian",term:"封",pinyin:"fēng",meaning:"界限、边界。【古今异义】非「封闭/封赏」，此处指事物之间的分界。未始有封：从来没有界限之分。"},{id:"shifei_zhizhi",term:"是非",pinyin:"shì fēi",meaning:"是与非的判断。认知第三层：有物有封但未有是非，是比有是非更高的境界。"},{id:"zhang_xianlu",term:"彰",pinyin:"zhāng",meaning:"彰显、显露。是非之彰：是非判断一旦彰显出来。"},{id:"kui_sunhao",term:"亏",pinyin:"kuī",meaning:"亏损、损伤。道之所以亏：道之所以受到损伤。是非彰则道亏，爱憎偏好则成见生。"},{id:"ai_pianhao",term:"爱",pinyin:"ài",meaning:"偏爱、偏好。【古今异义】此处非泛指「爱」，而是偏执的爱好，即成见的来源。"},{id:"cheng_xingcheng",term:"成",pinyin:"chéng",meaning:"形成、产生。爱之所以成：偏爱之所以形成（道亏则爱偏生）。"},{id:"guo_jiujing",term:"果",pinyin:"guǒ",meaning:"究竟、到底。疑问副词，表追问。"},{id:"qie_nandao",term:"且",pinyin:"qiě",meaning:"难道、究竟。副词，与「果」连用加强反问语气。"},{id:"zhaoshi",term:"昭氏",pinyin:"zhāo shì",meaning:"昭文，古代著名琴师。昭氏鼓琴：昭文弹琴时，弹出某音则其他音缺失，即有成有亏；不弹则诸音俱在，无成无亏。"},{id:"guqin",term:"鼓琴",pinyin:"gǔ qín",meaning:"弹奏琴。鼓：弹奏、敲击。【古今异义】鼓非「鼓乐器」，此处为动词「弹奏」。"},{id:"shikuang_zhice",term:"师旷之枝策也",pinyin:"shī kuàng zhī zhī cè yě",meaning:"师旷执节拍打节奏。师旷：晋国著名乐师，据说天生失明；枝策：执杖击节，打节拍。"},{id:"huizi_juwu",term:"惠子之据梧也",pinyin:"huì zǐ zhī jù wú yě",meaning:"惠子倚着梧桐树（辩论）。惠子：庄子的辩友；据梧：倚靠梧桐，指惠子倚树辩论的姿态。"},{id:"sanzi",term:"三子",pinyin:"sān zǐ",meaning:"三位：昭文、师旷、惠子。"},{id:"zhi_de",term:"之",pinyin:"zhī",meaning:"结构助词，的。三子之知：三人的才智。"},{id:"zhijhu",term:"知几乎",pinyin:"zhī jī hū",meaning:"才智接近（极致）了吧。知：才智；几：接近；乎：语气词，表揣测。"},{id:"jieqishengzhe",term:"皆其盛者也",pinyin:"jiē qí shèng zhě yě",meaning:"都是各自领域最鼎盛的人。盛：最盛、顶峰；者：代词。"},{id:"zai_monian",term:"载之末年",pinyin:"zài zhī mò nián",meaning:"将这（技艺）延续到晚年。载：承载、延续；末年：晚年、终年。指三子终身沉浸于此。"},{id:"haozhiye",term:"唯其好之也",pinyin:"wéi qí hào zhī yě",meaning:"正因为他们偏好（自己的技艺）。好：偏好、执着；之：代词，指各自的技艺。"},{id:"yiyubi",term:"以异于彼",pinyin:"yǐ yì yú bǐ",meaning:"因此与他人不同、标新立异。以：因此；异于彼：与别人不同。"},{id:"yuyiming",term:"欲以明之",pinyin:"yù yǐ míng zhī",meaning:"想要用（自己的技艺）来阐明（道）。欲：想要；以明之：用来彰明道理。"},{id:"jianbaimeizong",term:"坚白之昧终",pinyin:"jiān bái zhī mèi zhōng",meaning:"以坚白论的迷昧终其一生。坚白：公孙龙「坚白石」之辩，惠子亦好此类名辩；昧：迷昧、糊涂；终：终结一生。"},{id:"wenzhi_lunzhong",term:"文之纶终",pinyin:"wén zhī lún zhōng",meaning:"以昭文（父）的琴艺传承终其一生。文：昭文；纶：丝线，引申为传承脉络；终：终结。指昭文之子继承父业却终身无成。"},{id:"huayi_yaoyao",term:"滑疑之耀",pinyin:"gǔ yí zhī yào",meaning:"混沌疑惑中的光耀。滑：通「汩」，混乱；疑：疑惑不定；耀：光辉。指超越是非成毁的混沌之明，圣人以此为归。⚠️ 滑读 gǔ，非 huá。"},{id:"shengren_suotu",term:"圣人之所图",pinyin:"shèng rén zhī suǒ tú",meaning:"圣人所追求谋划的。图：谋求、追求。圣人不追求名辩是非，而追求滑疑之耀。"},{id:"yiming",term:"以明",pinyin:"yǐ míng",meaning:"用自然之明观照。呼应上段「莫若以明」，此处点明「以明」的真正含义：不用成心是非，而寓诸庸，顺道自然。"}],b=[{id:"baoguang_s1",label:"今且有言于此……其果无谓乎",sentences:[["今且有言于此，不知其",{text:"与是类乎",glossary:"yushi_lei"},"？其",{text:"与是不类乎",glossary:"yushi_lei"},"？"],[{text:"类与不类",glossary:"lei_bulei"},"，",{text:"相与为类",glossary:"xiangwei_lei"},"，则与",{text:"彼",glossary:"bi_duifang"},{text:"无以异矣",glossary:"wuyi_yi"},"。"],[{text:"虽然",glossary:"suiran_gu"},"，",{text:"请尝言之",glossary:"qingchang_yanzhi"},"："],[{text:"有始也者",glossary:"youshi_zhe"},"，",{text:"有未始有始也者",glossary:"weishi_youshi"},"，",{text:"有未始有夫未始有始也者",glossary:"fu_weishi"},"；"],[{text:"有有也者",glossary:"youyou_zhe"},"，",{text:"有无也者",glossary:"youwu_zhe"},"，",{text:"有未始有无也者",glossary:"weishi_youwu"},"，有未始有夫未始有无也者。"],[{text:"俄",glossary:"e_huran"},"而有无矣，",{text:"而",glossary:"er_dan"},"未知有无之",{text:"果",glossary:"guo_jiujing2"},"孰有孰无也。"],["今我则",{text:"已有有谓矣",glossary:"youyou_wei"},"，而未知",{text:"吾所谓之",glossary:"suowei_zhi"},"其果有谓乎？其果无谓乎？"]]},{id:"baoguang_s2",label:"夫天下莫大于秋豪之末……无适焉因是已",sentences:[["夫天下莫大于",{text:"秋豪之末",glossary:"qiuhao_zhi_mo"},"，而",{text:"太山为小",glossary:"taishan_xiao"},"；"],[{text:"莫寿乎殇子",glossary:"moshou_shangzi"},"，而",{text:"彭祖",glossary:"pengzu"},"为",{text:"夭",glossary:"yao_duoming"},"。"],["天地与我并生，而万物与我为一。"],["既已为一矣，且得有言乎？既已谓之一矣，且得无言乎？"],[{text:"一与言为二",glossary:"yi_yan_er"},"，",{text:"二与一为三",glossary:"er_yi_san"},"。"],[{text:"自此以往",glossary:"zici_yiwang"},"，",{text:"巧历",glossary:"qiaoli"},"不能得，而况其",{text:"凡",glossary:"fan_putong"},"乎！"],["故",{text:"自无适有",glossary:"ziwu_shiyou"},"，以至于三，而况",{text:"自有适有",glossary:"ziyou_shiyou"},"乎！"],[{text:"无适焉",glossary:"wu_shiyan"},"，",{text:"因是已",glossary:"yinshi_yi2"},"！"]]},{id:"bade_s1",label:"夫道未始有封……此之谓八德",sentences:[["夫道未始有",{text:"封",glossary:"feng_jiexian2"},"，言未始有",{text:"常",glossary:"chang_guiding"},"，为是而有",{text:"畛",glossary:"zhen_jiexian"},"也。"],["请言其畛：有左有右，有",{text:"伦",glossary:"lun_lunli"},"有",{text:"义",glossary:"yi_yili"},"，有分有",{text:"辩",glossary:"bian_bianlun"},"，有竞有争，此之谓",{text:"八德",glossary:"bade"},"。"],[{text:"六合",glossary:"liuhe"},"之外，圣人",{text:"存而不论",glossary:"cun_bulun"},"；"],["六合之内，圣人",{text:"论而不议",glossary:"lun_buyi"},"；"],["春秋经世先王之志，圣人",{text:"议而不辩",glossary:"yi_bubian"},"。"]]},{id:"bade_s2",label:"故分也者有不分也……辩也者有不见也",sentences:[["故",{text:"分也者",glossary:"fen_buzhi"},"，有不分也；",{text:"辩也者",glossary:"bian_buzhi"},"，有不辩也。"],["曰：「何也？」"],["「圣人",{text:"怀之",glossary:"huaizhi"},"，众人辩之以",{text:"相示",glossary:"xiangshi"},"也。"],["故曰：辩也者，有不见也。」"]]},{id:"dadao_s1",label:"夫大道不称……大勇不忮",sentences:[["夫",{text:"大道不称",glossary:"dadao_bucheng"},"，",{text:"大辩不言",glossary:"dabian_buyan"},"，",{text:"大仁不仁",glossary:"daren_buren"},"，",{text:"大廉不谦",glossary:"dalian_buqian"},"，",{text:"大勇不忮",glossary:"dayong_buzhi"},"。"],[{text:"道昭而不道",glossary:"dao_zhao_budao"},"，",{text:"言辩而不及",glossary:"yan_bian_buji"},"，"],[{text:"仁常而不成",glossary:"ren_chang_bucheng"},"，",{text:"廉清而不信",glossary:"lian_qing_buxin"},"，",{text:"勇忮而不成",glossary:"yong_zhi_bucheng"},"。"],[{text:"五者圆",glossary:"wuzhe_yuan"},"而",{text:"几向方矣",glossary:"ji_xiangfang"},"！"]]},{id:"dadao_s2",label:"故知止其所不知……此之谓葆光",sentences:[["故",{text:"知",glossary:"zhi_zhihui"},{text:"止其所不知",glossary:"zhi_suobuzhi"},"，",{text:"至",glossary:"zhi_jizhi2"},"矣。"],["孰知",{text:"不言之辩",glossary:"buyan_zhibian"},"，",{text:"不道之道",glossary:"budao_zhidao"},"？"],["若有能知，此之谓",{text:"天府",glossary:"tianfu"},"。"],[{text:"注焉而不满",glossary:"zhu_buman"},"，",{text:"酌焉而不竭",glossary:"zhuo_bujie"},"，而不知其所由来，此之谓",{text:"葆光",glossary:"baoguang"},"。"]]}],w=[{id:"yushi_lei",term:"与是类乎",pinyin:"yǔ shì lèi hū",meaning:"与这些（前文所说的道理）同类吗？与：和、跟；是：这；类：同类。"},{id:"lei_bulei",term:"类与不类",pinyin:"lèi yǔ bù lèi",meaning:"同类与不同类。庄子指出：同类与不同类本身也构成一类，故无绝对的类与不类之分。"},{id:"xiangwei_lei",term:"相与为类",pinyin:"xiāng yǔ wéi lèi",meaning:"相互构成一类。相与：相互；为类：成为同类。类与不类相互依存，本身即构成更大的「类」。"},{id:"bi_duifang",term:"彼",pinyin:"bǐ",meaning:"那个、对方。此处指万物、他者。与彼无以异：与万物没有什么不同。"},{id:"wuyi_yi",term:"无以异矣",pinyin:"wú yǐ yì yǐ",meaning:"没有什么不同了。无以：没有用来……的；异：区别、不同。"},{id:"suiran_gu",term:"虽然",pinyin:"suī rán",meaning:"虽然如此。【古今异义】古义为「虽然如此」，是「虽然这样」的意思，后文仍要转折陈述；非现代单纯的转折连词。"},{id:"qingchang_yanzhi",term:"请尝言之",pinyin:"qǐng cháng yán zhī",meaning:"请让我试着说说。请：表谦敬；尝：尝试；言之：说这件事。"},{id:"youshi_zhe",term:"有始也者",pinyin:"yǒu shǐ yě zhě",meaning:"有「开始」这回事的（层次）。也者：语气助词，表提顿。庄子列举时间认知的三个层次。"},{id:"weishi_youshi",term:"有未始有始也者",pinyin:"yǒu wèi shǐ yǒu shǐ yě zhě",meaning:"有「从未有过开始」这回事的（层次）。未始：从未；比「有始」更高一层，否定开始的存在。"},{id:"fu_weishi",term:"有未始有夫未始有始也者",pinyin:"yǒu wèi shǐ yǒu fū wèi shǐ yǒu shǐ yě zhě",meaning:"有「从未有过『从未有过开始』」这回事的（层次）。夫：那个，指示代词，指上一层；三重否定，认知的最高层次。"},{id:"youyou_zhe",term:"有有也者",pinyin:"yǒu yǒu yě zhě",meaning:"有「存在」这回事的（层次）。对应存在论的第一层：承认万物存在。"},{id:"youwu_zhe",term:"有无也者",pinyin:"yǒu wú yě zhě",meaning:"有「不存在/虚无」这回事的（层次）。承认虚无的存在，比「有有」更进一层。"},{id:"weishi_youwu",term:"有未始有无也者",pinyin:"yǒu wèi shǐ yǒu wú yě zhě",meaning:"有「从未有过虚无」这回事的（层次）。连「无」本身也否定，超越有无对立。"},{id:"e_huran",term:"俄",pinyin:"é",meaning:"忽然、顷刻间。表示时间极短。俄而：忽然间。"},{id:"er_dan",term:"而",pinyin:"ér",meaning:"但是、然而。连词，表转折。"},{id:"guo_jiujing2",term:"果",pinyin:"guǒ",meaning:"究竟、到底。疑问副词，表追问。"},{id:"youyou_wei",term:"已有有谓矣",pinyin:"yǐ yǒu yǒu wèi yǐ",meaning:"已经有了「有所言说」这回事了。已：已经；有谓：有所言说、有所指称；矣：语气词。"},{id:"suowei_zhi",term:"吾所谓之",pinyin:"wú suǒ wèi zhī",meaning:"我所说的这些话。所谓：所说的；之：代词，指上文所言。"},{id:"qiuhao_zhi_mo",term:"秋豪之末",pinyin:"qiū háo zhī mò",meaning:"秋天兽毛的末梢，极言细小。豪通「毫」；秋天兽毛新生最细；末：尖端。【通假字】比喻极小之物。"},{id:"taishan_xiao",term:"太山为小",pinyin:"tài shān wéi xiǎo",meaning:"泰山反而是小的。太山：即泰山；为小：显得渺小。与「秋豪之末」对举，说明大小相对，无绝对标准。"},{id:"moshou_shangzi",term:"莫寿乎殇子",pinyin:"mò shòu hū shāng zǐ",meaning:"没有比夭折的孩子更长寿的。殇子：未成年而死的孩子；莫寿乎：没有比……更长寿。以相对论说明寿夭无绝对。"},{id:"pengzu",term:"彭祖",pinyin:"péng zǔ",meaning:"传说中的长寿者，据说活了八百岁。此处反说彭祖为夭，与殇子对举，极言寿夭相对。"},{id:"yao_duoming",term:"夭",pinyin:"yāo",meaning:"短命、夭折。彭祖为夭：彭祖反而是短命的。与「莫寿乎殇子」构成悖论，说明寿夭皆相对。"},{id:"yi_yan_er",term:"一与言为二",pinyin:"yī yǔ yán wéi èr",meaning:"「一」加上「言」（说出「一」这个字）就成了二。一旦用语言表达「一」，语言本身就是另一个存在，故为二。"},{id:"er_yi_san",term:"二与一为三",pinyin:"èr yǔ yī wéi sān",meaning:"「二」再加上「一」又成了三。数字与概念不断叠加，无穷无尽，说明语言无法穷尽道。"},{id:"zici_yiwang",term:"自此以往",pinyin:"zì cǐ yǐ wǎng",meaning:"从此以后、照此推算下去。往：前往、推进。"},{id:"qiaoli",term:"巧历",pinyin:"qiǎo lì",meaning:"善于计算的人、精通历算的人。巧：善于；历：历算、计数。极言善算者也无法穷尽。"},{id:"fan_putong",term:"凡",pinyin:"fán",meaning:"普通人、平常人。【古今异义】非「凡是」，此处指普通人，与「巧历」对举。"},{id:"ziwu_shiyou",term:"自无适有",pinyin:"zì wú shì yǒu",meaning:"从无到有。适：到、往；自无适有：从虚无出发到达存在，已至于三，何况从有到有更无穷尽。"},{id:"ziyou_shiyou",term:"自有适有",pinyin:"zì yǒu shì yǒu",meaning:"从有到有。指在已有存在的基础上继续推演，数目更无穷尽。"},{id:"wu_shiyan",term:"无适焉",pinyin:"wú shì yān",meaning:"不要去推算它（数目）。无：不要，否定祈使；适：前往、追求；焉：语气词。"},{id:"yinshi_yi2",term:"因是已",pinyin:"yīn shì yǐ",meaning:"顺应这个（道）就够了。与上段「因是已」同义，呼应。"},{id:"feng_jiexian2",term:"封",pinyin:"fēng",meaning:"界限、边界。道未始有封：道从来没有固定的界限。与上段「未始有封」呼应。"},{id:"chang_guiding",term:"常",pinyin:"cháng",meaning:"固定的标准、常规。言未始有常：言语从来没有固定不变的标准。"},{id:"zhen_jiexian",term:"畛",pinyin:"zhěn",meaning:"田间界路，引申为界限、分际。为是而有畛：正因为（人为划分）才有了这些界限。"},{id:"lun_lunli",term:"伦",pinyin:"lún",meaning:"伦理、顺序。有伦有义：有伦理秩序，有道义准则。"},{id:"yi_yili",term:"义",pinyin:"yì",meaning:"道义、准则。与「伦」并举，指人伦道义的规范。"},{id:"bian_bianlun",term:"辩",pinyin:"biàn",meaning:"辩论、辨别。有分有辩：有分别有辩论。"},{id:"bade",term:"八德",pinyin:"bā dé",meaning:"八种界限/德目：左右、伦义、分辩、竞争。德：此处非「道德」，而是「类别/界限」。八德即人为划分出的八种分际，是道被遮蔽后的产物。"},{id:"liuhe",term:"六合",pinyin:"liù hé",meaning:"上下四方，即宇宙空间。六合之外：宇宙之外，指超越人知范围的领域。"},{id:"cun_bulun",term:"存而不论",pinyin:"cún ér bù lùn",meaning:"存而不论：承认其存在但不加讨论。存：保留、承认；不论：不讨论。圣人对超出认知范围的事物的态度。"},{id:"lun_buyi",term:"论而不议",pinyin:"lùn ér bù yì",meaning:"论述但不评议。论：陈述事实；议：评议是非。圣人对六合之内事物的态度：陈述而不妄加评议。"},{id:"yi_bubian",term:"议而不辩",pinyin:"yì ér bù biàn",meaning:"评议但不争辩。议：评议；辩：争辩是非。圣人对历史典籍的态度：评议而不争辩。三层递进：存而不论→论而不议→议而不辩。"},{id:"fen_buzhi",term:"分也者",pinyin:"fēn yě zhě",meaning:"能分辨的（智慧）。分：分辨、区别；也者：提顿语气。有不分：有不能分辨的地方，即知止。"},{id:"bian_buzhi",term:"辩也者",pinyin:"biàn yě zhě",meaning:"能辩论的（智慧）。有不辩：有不能辩论的地方，即大辩不言。"},{id:"huaizhi",term:"怀之",pinyin:"huái zhī",meaning:"将它（道）藏于心中。怀：怀藏、内守；之：代词，指道。圣人内守而不外辩，与众人「辩之以相示」形成对比。"},{id:"xiangshi",term:"相示",pinyin:"xiāng shì",meaning:"互相炫示、向他人展示。示：展示、炫耀。众人辩之以相示：众人争辩是为了向他人炫示自己的见解。"},{id:"dadao_bucheng",term:"大道不称",pinyin:"dà dào bù chēng",meaning:"最大的道不可名称。称：称呼、命名。道可道，非常道；真正的道超越一切名称。"},{id:"dabian_buyan",term:"大辩不言",pinyin:"dà biàn bù yán",meaning:"最大的辩才不用言语。真正的辩不在言辞，而在于默契与道。"},{id:"daren_buren",term:"大仁不仁",pinyin:"dà rén bù rén",meaning:"最大的仁不刻意施仁。刻意标榜的仁反而不是真仁，真仁出于自然无为。"},{id:"dalian_buqian",term:"大廉不谦",pinyin:"dà lián bù qiān",meaning:"最大的廉洁不表现为谦让。刻意谦让反而是廉的遮蔽，真廉自然无为。"},{id:"dayong_buzhi",term:"大勇不忮",pinyin:"dà yǒng bù zhì",meaning:"最大的勇不表现为强悍。忮：强悍、刚戾；真正的勇不需要以强悍示人。"},{id:"dao_zhao_budao",term:"道昭而不道",pinyin:"dào zhāo ér bù dào",meaning:"道一旦彰显出来就不是真道了。昭：彰显、显露；不道：不是道。可见之道非真道。"},{id:"yan_bian_buji",term:"言辩而不及",pinyin:"yán biàn ér bù jí",meaning:"言语辩论无法触及（真理）。及：到达、触及。辩越多，离道越远。"},{id:"ren_chang_bucheng",term:"仁常而不成",pinyin:"rén cháng ér bù chéng",meaning:"仁若成为常规就无法真正成就。常：固定化、常规化；不成：无法真正成就。"},{id:"lian_qing_buxin",term:"廉清而不信",pinyin:"lián qīng ér bù xìn",meaning:"廉洁清白若刻意表现反而不可信。清：清白；不信：不可信赖。"},{id:"yong_zhi_bucheng",term:"勇忮而不成",pinyin:"yǒng zhì ér bù chéng",meaning:"勇若表现为强悍刚戾就无法真正成就。忮：强悍刚戾；不成：无法成就真勇。"},{id:"wuzhe_yuan",term:"五者圆",pinyin:"wǔ zhě yuán",meaning:"这五者（道、辩、仁、廉、勇）本来是圆融的。圆：圆融、完整无缺。"},{id:"ji_xiangfang",term:"几向方矣",pinyin:"jī xiàng fāng yǐ",meaning:"却趋向方（有棱角、僵化）了。几：将要、趋向；方：方形，喻僵化执着；圆→方：自然圆融→人为僵化。"},{id:"zhi_zhihui",term:"知",pinyin:"zhī",meaning:"智慧、认知。知止其所不知：智慧在于知道停止于自己不知道的地方。"},{id:"zhi_suobuzhi",term:"止其所不知",pinyin:"zhǐ qí suǒ bù zhī",meaning:"停止于自己所不知道的地方。止：停止、知止；所不知：不知道的领域。不强求知道不可知之事，是最高的智慧。"},{id:"zhi_jizhi2",term:"至",pinyin:"zhì",meaning:"极致、最高境界。知止其所不知，至矣：能做到知止，就达到极致了。"},{id:"buyan_zhibian",term:"不言之辩",pinyin:"bù yán zhī biàn",meaning:"不用言语的辩才。呼应「大辩不言」，真正的辩超越言语。"},{id:"budao_zhidao",term:"不道之道",pinyin:"bù dào zhī dào",meaning:"不可言说的道。呼应「大道不称」，真正的道超越一切称谓。"},{id:"tianfu",term:"天府",pinyin:"tiān fǔ",meaning:"天然的府库。府：储藏之所；天府：自然无尽的宝库，比喻能容纳一切、取之不尽的心灵境界。"},{id:"zhu_buman",term:"注焉而不满",pinyin:"zhù yān ér bù mǎn",meaning:"不断注入却不会满溢。注：灌注、注入；不满：不会溢满。形容天府（道）的无限容量。"},{id:"zhuo_bujie",term:"酌焉而不竭",pinyin:"zhuó yān ér bù jié",meaning:"不断汲取却不会枯竭。酌：舀取、汲取；不竭：不会穷尽。与「注焉而不满」对举，形容道的无限性。"},{id:"baoguang",term:"葆光",pinyin:"bǎo guāng",meaning:"蕴藏而不外露的光。葆：通「保」，蕴藏、保藏；光：智慧之光。不炫耀、不彰显，将光明内敛蕴藏，是圣人处世的最高境界。呼应全篇「莫若以明」。"}],c=[{id:"nique_s1",label:"啮缺问乎王倪……吾恶乎知之",sentences:[[{text:"啮缺",glossary:"nique"},"问乎",{text:"王倪",glossary:"wangni"},"曰：「子知",{text:"物之所同",glossary:"wuzhisuotong"},{text:"是乎",glossary:"shihu"},"？」"],["曰：「",{text:"吾恶乎知之",glossary:"wuewuhu"},"！」"],["「子知子之所不知邪？」曰：「吾恶乎知之！」"],["「然则物无知邪？」曰：「吾恶乎知之！"]]},{id:"nique_s2",label:"虽然尝试言之……庸讵知吾所谓不知之非知邪",sentences:[["虽然，尝试言之：",{text:"庸讵",glossary:"yongju"},"知吾所谓知之非不知邪？",{text:"庸讵",glossary:"yongju"},"知吾所谓不知之非知邪？"]]},{id:"zhengchu_s1",label:"且吾尝试问乎女……三者孰知正处",sentences:[["且吾尝试问乎",{text:"女",glossary:"nv_ru"},"：民",{text:"湿寝",glossary:"shiqin"},"则",{text:"腰疾偏死",glossary:"yaoji_piansi"},"，",{text:"鳅然乎哉",glossary:"qiu_ranhu"},"？"],[{text:"木处",glossary:"muchu"},"则",{text:"惴栗恂惧",glossary:"zhui_xunjv"},"，",{text:"猨猴然乎哉",glossary:"yuanhou_ranhu"},"？"],["三者孰知",{text:"正处",glossary:"zhengchu"},"？"]]},{id:"zhengwei_s1",label:"民食刍豢……四者孰知正味",sentences:[["民食",{text:"刍豢",glossary:"chuhuan"},"，麋鹿食",{text:"荐",glossary:"jian_cao"},"，",{text:"蝍蛆",glossary:"jiju"},{text:"甘带",glossary:"gandai"},"，",{text:"鸱鸦",glossary:"chiya"},{text:"耆",glossary:"qi_shi"},{text:"腐鼠",glossary:"fushu"},"，"],["四者孰知",{text:"正味",glossary:"zhengwei"},"？"]]},{id:"zhengse_s1",label:"猨猵狙以为雌……四者孰知天下之正色哉",sentences:[[{text:"猨猵",glossary:"yuanpian"},{text:"狙",glossary:"ju_hou"},"以为雌，麋与鹿交，鳅与鱼游。"],[{text:"毛嫱",glossary:"maoqiang"},"、",{text:"丽姬",glossary:"liji"},"，",{text:"人之所美也",glossary:"renzhisuomei"},"；"],[{text:"鱼见之深入",glossary:"yu_shenru"},"，",{text:"鸟见之高飞",glossary:"niao_gaofei"},"，麋鹿见之",{text:"决骤",glossary:"juezhou"},"。"],["四者孰知天下之",{text:"正色",glossary:"zhengse"},"哉？"]]},{id:"zhengse_s2",label:"自我观之……吾恶能知其辩",sentences:[["自我观之，仁义之",{text:"端",glossary:"duan_kaishi"},"，是非之",{text:"涂",glossary:"tu_daolu"},"，",{text:"樊然淆乱",glossary:"fanran_xiaoluan"},"，",{text:"吾恶能知其辩",glossary:"wu_nengzhi_bian"},"！」"]]},{id:"zhiren_s1",label:"啮缺曰子不知利害……至人固不知利害乎",sentences:[["啮缺曰：「子不知利害，则",{text:"至人",glossary:"zhiren"},"固不知利害乎？」"]]},{id:"zhiren_s2",label:"王倪曰至人神矣……而况利害之端乎",sentences:[["王倪曰：「",{text:"至人神矣",glossary:"zhiren_shen"},"！"],[{text:"大泽",glossary:"daze"},{text:"焚",glossary:"fen_ranshao"},"而不能",{text:"热",glossary:"re_shangren"},"，"],[{text:"河汉",glossary:"hehan"},{text:"冱",glossary:"hu_donghe"},"而不能",{text:"寒",glossary:"han_dongshang"},"，"],[{text:"疾雷破山",glossary:"jilei_poshan"},"、",{text:"飘风振海",glossary:"piaofeng_zhenhai"},"而不能",{text:"惊",glossary:"jing_jingdong"},"。"],[{text:"若然者",glossary:"ruoranzhe"},"，乘云气，骑日月，而游乎四海之外。"],["死生",{text:"无变",glossary:"wubian"},{text:"于己",glossary:"yuji"},"，而",{text:"况",glossary:"kuang_hegeng"},{text:"利害之端",glossary:"lihai_zhiduan"},"乎！」"]]}],j=[{id:"nique",term:"啮缺",pinyin:"niè quē",meaning:"庄子寓言中的人物，求道者，王倪之弟子。啮：咬；缺：缺口。名字本身暗示残缺不全，喻认知的局限。"},{id:"wangni",term:"王倪",pinyin:"wáng ní",meaning:"庄子寓言中的人物，得道者，以「吾恶乎知之」三答展示知止之境。"},{id:"wuzhisuotong",term:"物之所同",pinyin:"wù zhī suǒ tóng",meaning:"万物共同认可的（标准）。所同：共同认可之处；是：对、正确。物之所同是：万物共同认为对的。"},{id:"shihu",term:"是乎",pinyin:"shì hū",meaning:"对吗？是否正确？是：对、正确；乎：疑问语气词。"},{id:"wuewuhu",term:"吾恶乎知之",pinyin:"wú wū hū zhī zhī",meaning:"我怎么知道呢？恶乎：怎么、从哪里；知之：知道这件事。王倪三次以此作答，体现「知止」的智慧。"},{id:"yongju",term:"庸讵",pinyin:"yōng jù",meaning:"怎么、哪里。疑问副词连用。庸：怎么；讵：岂、哪里。【古今异义】庸非「平庸」，讵非常用字，均为疑问副词。"},{id:"nv_ru",term:"女",pinyin:"rǔ",meaning:"你。通「汝」。【通假字】⚠️ 读 rǔ，非「女性」义。"},{id:"shiqin",term:"湿寝",pinyin:"shī qǐn",meaning:"在潮湿的地方睡觉。湿：潮湿；寝：睡觉。"},{id:"yaoji_piansi",term:"腰疾偏死",pinyin:"yāo jí piān sǐ",meaning:"腰部生病甚至半身不遂而死。腰疾：腰部疾病；偏死：半身偏瘫而死。人在湿地睡觉的后果。"},{id:"qiu_ranhu",term:"鳅然乎哉",pinyin:"qiū rán hū zāi",meaning:"泥鳅也是这样吗？鳅：泥鳅，生活在泥水中；然乎哉：是这样的吗？反问：泥鳅以湿地为正处，人却以为苦。"},{id:"muchu",term:"木处",pinyin:"mù chǔ",meaning:"在树上居住。木：树木；处：居住。"},{id:"zhui_xunjv",term:"惴栗恂惧",pinyin:"zhuì lì xún jù",meaning:"战战兢兢、恐惧不安。惴：忧惧；栗：颤抖；恂：恐惧；惧：害怕。四字叠用，极言人在树上的恐惧。"},{id:"yuanhou_ranhu",term:"猨猴然乎哉",pinyin:"yuán hóu rán hū zāi",meaning:"猿猴也是这样吗？猨：通「猿」；猴：猴子。反问：猿猴以树上为正处，人却以为险。"},{id:"zhengchu",term:"正处",pinyin:"zhèng chǔ",meaning:"正确的居处、最适宜的栖居之所。庄子以此反问：居处无绝对正确，各物有其所宜。"},{id:"chuhuan",term:"刍豢",pinyin:"chú huàn",meaning:"牲畜肉食。刍：草食动物（牛羊）；豢：谷食动物（猪狗）。刍豢：泛指人所饲养的牲畜，即肉食。"},{id:"jian_cao",term:"荐",pinyin:"jiàn",meaning:"野草、草地。麋鹿食荐：麋鹿以野草为食。【古今异义】非「推荐」，此处为「草」义。"},{id:"jiju",term:"蝍蛆",pinyin:"jí jū",meaning:"蜈蚣。蝍蛆：即蜈蚣，多足虫。"},{id:"gandai",term:"甘带",pinyin:"gān dài",meaning:"以蛇为甘美之食。甘：以……为甘美，意动用法；带：蛇。蝍蛆甘带：蜈蚣以蛇为美食。"},{id:"chiya",term:"鸱鸦",pinyin:"chī yā",meaning:"猫头鹰与乌鸦。鸱：猫头鹰；鸦：乌鸦。两者皆以腐物为食。"},{id:"qi_shi",term:"耆",pinyin:"shì",meaning:"嗜好、喜爱。通「嗜」。⚠️ 读 shì，非「老人」义（耆老读 qí）。【通假字】"},{id:"fushu",term:"腐鼠",pinyin:"fǔ shǔ",meaning:"腐烂的死鼠。鸱鸦以腐鼠为美食，与人食刍豢形成对比。"},{id:"zhengwei",term:"正味",pinyin:"zhèng wèi",meaning:"正确的味道、最美的食物。庄子以此反问：口味无绝对正确，各物有其所嗜。"},{id:"yuanpian",term:"猨猵",pinyin:"yuán piān",meaning:"猿与猵狙（一种猴）。猨：通「猿」；猵：猵狙，一种猴类。"},{id:"ju_hou",term:"狙",pinyin:"jū",meaning:"猕猴、猿猴。猨猵狙以为雌：猿猴以猿猴为配偶，各从其类。"},{id:"maoqiang",term:"毛嫱",pinyin:"máo qiáng",meaning:"古代著名美女，传说为越王勾践之爱姬。与丽姬并举，代表人类公认的美丽。"},{id:"liji",term:"丽姬",pinyin:"lì jī",meaning:"即骊姬，晋献公之宠姬，以美貌著称。与毛嫱并举，代表人类公认的美丽。"},{id:"renzhisuomei",term:"人之所美也",pinyin:"rén zhī suǒ měi yě",meaning:"人们所认为美丽的。所美：所认为美的；也：判断语气词。"},{id:"yu_shenru",term:"鱼见之深入",pinyin:"yú jiàn zhī shēn rù",meaning:"鱼见到她们就潜入深水。深入：潜入深处，以逃避。鱼以人类美女为恐惧之物。"},{id:"niao_gaofei",term:"鸟见之高飞",pinyin:"niǎo jiàn zhī gāo fēi",meaning:"鸟见到她们就高飞远去。高飞：飞向高处，以逃避。鸟以人类美女为恐惧之物。"},{id:"juezhou",term:"决骤",pinyin:"jué zhòu",meaning:"奔逃疾驰。决：快速奔跑；骤：急驰。麋鹿见到美女拔腿就跑，与人类「人之所美」形成强烈对比。"},{id:"zhengse",term:"正色",pinyin:"zhèng sè",meaning:"正确的美色、天下公认的美丽。庄子以此反问：美色无绝对标准，各物有其所美。正处·正味·正色三问，共同指向：是非美丑皆无客观标准。"},{id:"duan_kaishi",term:"端",pinyin:"duān",meaning:"起点、端绪。仁义之端：仁义的起点与界限。【古今异义】非「端正」，此处为「端绪/起点」。"},{id:"tu_daolu",term:"涂",pinyin:"tú",meaning:"道路、途径。通「途」。是非之涂：是非所走的道路，即是非的种种表现。【通假字】"},{id:"fanran_xiaoluan",term:"樊然淆乱",pinyin:"fán rán xiáo luàn",meaning:"纷乱混杂的样子。樊然：纷乱的样子；淆乱：混乱交杂。形容仁义是非纷繁复杂、无从辨别。"},{id:"wu_nengzhi_bian",term:"吾恶能知其辩",pinyin:"wú wū néng zhī qí biàn",meaning:"我怎么能知道其中的分辨？恶：怎么；能：能够；辩：分辨、区别。与开篇「吾恶乎知之」呼应，王倪以「不知」贯穿全段。"},{id:"zhiren",term:"至人",pinyin:"zhì rén",meaning:"达到最高境界的人。至：极致；至人：庄子理想人格之一，与神人、圣人并列。"},{id:"zhiren_shen",term:"至人神矣",pinyin:"zhì rén shén yǐ",meaning:"至人真是神奇啊！神：神奇、超越常人；矣：感叹语气词。"},{id:"daze",term:"大泽",pinyin:"dà zé",meaning:"大片沼泽、大湖泽。大泽焚：大泽燃烧，极言火势之猛。"},{id:"fen_ranshao",term:"焚",pinyin:"fén",meaning:"燃烧、焚烧。大泽焚：大泽着火，极言热之极。"},{id:"re_shangren",term:"热",pinyin:"rè",meaning:"使……感到热、伤热。动词，使动用法。不能热：不能使至人感到热。"},{id:"hehan",term:"河汉",pinyin:"hé hàn",meaning:"黄河与汉水，泛指大河。河汉冱：大河冻结，极言寒之极。"},{id:"hu_donghe",term:"冱",pinyin:"hù",meaning:"冻结、凝固。河汉冱：黄河汉水冻结成冰。⚠️ 生僻字，读 hù。"},{id:"han_dongshang",term:"寒",pinyin:"hán",meaning:"使……感到寒冷。动词，使动用法。不能寒：不能使至人感到寒冷。与「热」对举。"},{id:"jilei_poshan",term:"疾雷破山",pinyin:"jí léi pò shān",meaning:"迅猛的雷声震裂山岳。疾：迅猛；破：震裂。极言声势之大。"},{id:"piaofeng_zhenhai",term:"飘风振海",pinyin:"piāo fēng zhèn hǎi",meaning:"狂风震动大海。飘风：疾风、狂风；振：震动。极言风势之猛。"},{id:"jing_jingdong",term:"惊",pinyin:"jīng",meaning:"使……受到惊吓。动词，使动用法。不能惊：不能使至人受惊。热·寒·惊三者皆使动，结构一致。"},{id:"ruoranzhe",term:"若然者",pinyin:"ruò rán zhě",meaning:"像这样的人。若然：像这样；者：代词，指至人。"},{id:"wubian",term:"无变",pinyin:"wú biàn",meaning:"没有变化、不受影响。死生无变：死生对至人没有影响。"},{id:"yuji",term:"于己",pinyin:"yú jǐ",meaning:"对自己（而言）。于：介词，对于；己：自身。"},{id:"kuang_hegeng",term:"况",pinyin:"kuàng",meaning:"何况、更何况。递进连词，表示更进一步的推论。"},{id:"lihai_zhiduan",term:"利害之端",pinyin:"lì hài zhī duān",meaning:"利害得失的细枝末节。端：端绪、细节。死生尚且无变于己，何况区区利害？层层递进。"}],q=[{id:"liji_s1",label:"瞿鹊子问乎长梧子……吾子以为奚若",sentences:[[{text:"瞿鹊子",glossary:"jujuezi"},"问乎",{text:"长梧子",glossary:"changwuzi"},"曰：「吾闻",{text:"诸夫子",glossary:"zhufuzi"},"："],["圣人不",{text:"从事于务",glossary:"congshi_wu"},"，不",{text:"就利",glossary:"jiuli"},"，不",{text:"违害",glossary:"weihai"},"，不",{text:"喜求",glossary:"xiqiu"},"，不",{text:"缘道",glossary:"yuandao"},"；"],[{text:"无谓有谓",glossary:"wuwei_youwei"},"，",{text:"有谓无谓",glossary:"youwei_wuwei"},"，而游乎",{text:"尘垢之外",glossary:"chengou_wai"},"。"],["夫子以为",{text:"孟浪之言",glossary:"menglang_yan"},"，而我以为",{text:"妙道之行也",glossary:"miaodao_xing"},"。",{text:"吾子",glossary:"wuzi_nin"},{text:"以为",glossary:"yiwei_renwei"},{text:"奚若",glossary:"xiruuo"},"？」"]]},{id:"liji_s2",label:"长梧子曰是黄帝之所听荧也……以隶相尊",sentences:[["长梧子曰：「是黄帝之所",{text:"听荧",glossary:"tingying"},"也，而",{text:"丘",glossary:"qiu_kongzi"},"也何足以知之！"],["且",{text:"女",glossary:"nv_ru2"},"亦",{text:"大早计",glossary:"da_zaoji"},"，",{text:"见卵",glossary:"jianluan"},"而",{text:"求时夜",glossary:"qiu_shiye"},"，",{text:"见弹",glossary:"jian_dan"},"而",{text:"求鸮炙",glossary:"qiu_xiaozhi"},"。"],[{text:"予",glossary:"yu_wo"},{text:"尝为",glossary:"chang_wei"},"女妄言之，女以妄听之。"],[{text:"奚旁日月",glossary:"xi_pang_riyue"},"，",{text:"挟宇宙",glossary:"xie_yuzhou"},"，为其",{text:"吻合",glossary:"wenhe_gu"},"，置其",{text:"滑涽",glossary:"huahun"},"，以",{text:"隶相尊",glossary:"li_xiangzun"},"？"]]},{id:"liji_s3",label:"众人役役……而以是相蕴",sentences:[["众人",{text:"役役",glossary:"yiyi_laoku2"},"，圣人",{text:"愚芚",glossary:"yutun"},"，",{text:"参万岁",glossary:"can_wansui"},"而",{text:"一成纯",glossary:"yi_chengchun"},"。"],["万物尽然，而以是",{text:"相蕴",glossary:"xiangyun"},"。"]]},{id:"liji_s4",label:"予恶乎知说生之非惑邪……而后悔其泣也",sentences:[[{text:"予恶乎",glossary:"yu_ewuhu"},"知",{text:"说生之",glossary:"yuesheng_zhi"},{text:"非惑邪",glossary:"fei_huo"},"？"],["予恶乎知",{text:"恶死之",glossary:"wusi_zhi"},{text:"非弱丧",glossary:"ruo_sang"},"而不知",{text:"归者",glossary:"guizhe"},"邪？"],[{text:"丽之姬",glossary:"liji_ren"},"，",{text:"艾封人之子也",glossary:"ai_fengren"},"。"],[{text:"晋国之",glossary:"jin_guo"},{text:"始得之",glossary:"shi_dezhi"},"也，",{text:"涕泣沾襟",glossary:"tiqi_zhanjin"},"；"],[{text:"及",glossary:"ji_dengdao"},{text:"其",glossary:"qi_ta"},{text:"至",glossary:"zhi_daoda"},{text:"于",glossary:"yu_jie"},{text:"王所",glossary:"wangsuo"},"，"],[{text:"与",glossary:"yu_gen"},"王",{text:"同",glossary:"tong_gongtong"},{text:"筐床",glossary:"kuangchuang"},"，食",{text:"刍豢",glossary:"chuhuan2"},"，"],[{text:"而后",glossary:"erhou_cai"},{text:"悔其泣",glossary:"hui_qiqi"},"也。"]]},{id:"liji_s5",label:"予恶乎知夫死者……其始之蕲生乎",sentences:[["予恶乎知夫死者不悔",{text:"其",glossary:"qi_tade"},{text:"始之蕲生乎",glossary:"shi_qisheng"},"？"]]},{id:"dameng_s1",label:"梦饮酒者……觉而后知其梦也",sentences:[["梦饮酒者，",{text:"旦",glossary:"dan_zaocheng"},"而哭泣；梦哭泣者，旦而田猎。"],[{text:"方",glossary:"fang_zhengzai"},"其梦也，不知其梦也。梦之中又",{text:"占",glossary:"zhan_zhanbu"},"其梦焉，",{text:"觉而后知",glossary:"jue_erhouzhi"},"其梦也。"]]},{id:"dameng_s2",label:"且有大觉而后知此其大梦也……是旦暮遇之也",sentences:[["且有",{text:"大觉",glossary:"dajue"},"而后知此其",{text:"大梦",glossary:"dameng"},"也，而愚者自以为觉，",{text:"窃窃然知之",glossary:"qieqie_zhizhi"},"。"],[{text:"君乎",glossary:"jun_mu"},"，",{text:"牧乎",glossary:"jun_mu"},"，",{text:"固哉",glossary:"guzai"},"！"],[{text:"丘也与女",glossary:"qiu_yu_nv"},"，皆梦也；予谓女梦，亦梦也。"],["是其言也，其名为",{text:"吊诡",glossary:"diaogui"},"。"],[{text:"万世之后而一",glossary:"wanshi_eryi"},"遇大圣，知其解者，",{text:"是旦暮遇之也",glossary:"shi_danmu_yu"},"。」"]]}],f=[{id:"jujuezi",term:"瞿鹊子",pinyin:"jù què zǐ",meaning:"庄子寓言中的人物，求道者，向长梧子请教。名字含义：瞿：惊视的样子；鹊：喜鹊，象征浮躁求知。"},{id:"changwuzi",term:"长梧子",pinyin:"cháng wú zǐ",meaning:"庄子寓言中的得道者，以大梦之说回应瞿鹊子。梧：梧桐，象征高洁沉稳。"},{id:"zhufuzi",term:"诸夫子",pinyin:"zhū fū zǐ",meaning:"从夫子那里。诸：之于，兼词，诸=之+于；夫子：指孔子或某位老师。"},{id:"congshi_wu",term:"从事于务",pinyin:"cóng shì yú wù",meaning:"从事于世俗事务。务：世俗事务、功名利禄。圣人不从事于务：不执着于世俗事务。"},{id:"jiuli",term:"就利",pinyin:"jiù lì",meaning:"趋向利益。就：趋向、追求。不就利：不刻意追求利益。"},{id:"weihai",term:"违害",pinyin:"wéi hài",meaning:"回避祸害。违：回避、躲避。不违害：不刻意回避祸害。与「不就利」对举。"},{id:"xiqiu",term:"喜求",pinyin:"xǐ qiú",meaning:"喜好追求（道）。喜：喜好；求：追求。不喜求：不刻意追求道。"},{id:"yuandao",term:"缘道",pinyin:"yuán dào",meaning:"攀附于道、依循道而行。缘：攀附、依循。不缘道：不刻意依附道。五个「不」共同描绘圣人无为自然的境界。"},{id:"wuwei_youwei",term:"无谓有谓",pinyin:"wú wèi yǒu wèi",meaning:"无所言说却有所言说。无谓：无所指称；有谓：有所言说。指圣人言语超越有无之分。"},{id:"youwei_wuwei",term:"有谓无谓",pinyin:"yǒu wèi wú wèi",meaning:"有所言说却又无所言说。与「无谓有谓」互文，说明圣人言语出入有无之间，不执一端。"},{id:"chengou_wai",term:"尘垢之外",pinyin:"chén gòu zhī wài",meaning:"尘世污垢之外。尘垢：世俗的尘埃与污垢，比喻名利是非的世界；之外：超越其外。"},{id:"menglang_yan",term:"孟浪之言",pinyin:"mèng làng zhī yán",meaning:"荒诞不经的言论。孟浪：鲁莽荒唐、不着边际；之言：这样的话。夫子（孔子）认为此说荒诞。"},{id:"miaodao_xing",term:"妙道之行也",pinyin:"miào dào zhī xíng yě",meaning:"精妙之道的实践。妙道：精妙的道；行：实践、体现。瞿鹊子认为此说是妙道的体现。"},{id:"wuzi_nin",term:"吾子",pinyin:"wú zǐ",meaning:"您、先生。敬称，比「子」更尊敬。【古今异义】非「我的儿子」，而是对对方的尊称。"},{id:"yiwei_renwei",term:"以为",pinyin:"yǐ wéi",meaning:"认为。以：用；为：作为判断。"},{id:"xiruuo",term:"奚若",pinyin:"xī ruò",meaning:"如何、怎么样。奚：疑问代词，何；若：如。吾子以为奚若：您认为怎么样？"},{id:"tingying",term:"听荧",pinyin:"tīng yíng",meaning:"迷惑、困惑不解。听：听闻；荧：迷惑、眩惑。黄帝之所听荧：连黄帝听了都感到迷惑。"},{id:"qiu_kongzi",term:"丘",pinyin:"qiū",meaning:"孔子，名丘。长梧子以孔子自谦，或指孔子亦不足以知此道。"},{id:"nv_ru2",term:"女",pinyin:"rǔ",meaning:"你。通「汝」。【通假字】⚠️ 读 rǔ，非「女性」义。"},{id:"da_zaoji",term:"大早计",pinyin:"tài zǎo jì",meaning:"太过急于谋算、操之过急。大：通「太」；早计：过早地谋划打算。【通假字】大通「太」。"},{id:"jianluan",term:"见卵",pinyin:"jiàn luǎn",meaning:"看到鸡蛋。比喻事物尚在起点，就急于求成。"},{id:"qiu_shiye",term:"求时夜",pinyin:"qiú shí yè",meaning:"就想要（那只鸡来）报晓。时夜：司夜，指报晓的公鸡；时通「司」，主管。见卵求时夜：看到蛋就想要公鸡报晓，比喻急于求成。【通假字】时通「司」。"},{id:"jian_dan",term:"见弹",pinyin:"jiàn dàn",meaning:"看到弹丸。比喻事物尚在准备阶段。"},{id:"qiu_xiaozhi",term:"求鸮炙",pinyin:"qiú xiāo zhì",meaning:"就想要烤猫头鹰吃。鸮：猫头鹰；炙：烤肉。见弹求鸮炙：看到弹丸就想要烤鸟吃，与「见卵求时夜」并举，比喻瞿鹊子急于求道的心态。"},{id:"yu_wo",term:"予",pinyin:"yú",meaning:"我。第一人称代词。【古今异义】文言文中「予」与「余」皆为「我」，非「给予」。"},{id:"chang_wei",term:"尝为",pinyin:"cháng wèi",meaning:"姑且为（你）。尝：姑且、试着；为：为了、替。"},{id:"xi_pang_riyue",term:"奚旁日月",pinyin:"xī páng rì yuè",meaning:"怎么能傍着日月（而行）。奚：怎么；旁：通「傍」，依傍、靠近。【通假字】旁通「傍」。"},{id:"xie_yuzhou",term:"挟宇宙",pinyin:"xié yǔ zhòu",meaning:"挟持宇宙（于腋下）。挟：夹持、携带；宇宙：空间与时间的总称。形容圣人超越时空的宏大境界。"},{id:"wenhe_gu",term:"吻合",pinyin:"wěn hé",meaning:"使万物契合为一。吻：嘴唇，引申为密合；合：合一。【古今异义】非现代「完全符合」，此处指使万物融合为一体。"},{id:"huahun",term:"滑涽",pinyin:"gǔ hún",meaning:"混沌模糊的状态。滑：通「汩」，混乱；涽：昏昧混沌。置其滑涽：将混沌模糊的状态搁置一旁，不加分辨。⚠️ 滑读 gǔ。"},{id:"li_xiangzun",term:"以隶相尊",pinyin:"yǐ lì xiāng zūn",meaning:"用平等相待代替尊卑之分。隶：奴隶、卑贱者；以隶相尊：以对待奴隶的方式来互相尊重，即超越尊卑等级，平等视之。"},{id:"yiyi_laoku2",term:"役役",pinyin:"yì yì",meaning:"劳苦奔波、不停劳役。叠词，形容众人终身辛苦劳作，与上段「终身役役」呼应。"},{id:"yutun",term:"愚芚",pinyin:"yú tún",meaning:"浑然无知、大智若愚的样子。愚：愚钝；芚：草木初生的样子，引申为浑朴无知。圣人愚芚：圣人外表浑朴，不显智慧。"},{id:"can_wansui",term:"参万岁",pinyin:"cān wàn suì",meaning:"综合万年的变化。参：参合、综合；万岁：万年，极言时间之长。"},{id:"yi_chengchun",term:"一成纯",pinyin:"yī chéng chún",meaning:"归于纯一。一：归于一；成纯：成就纯粹。参万岁而一成纯：综合万年变化而归于纯一之道。"},{id:"xiangyun",term:"相蕴",pinyin:"xiāng yùn",meaning:"相互蕴含、彼此包容。蕴：蕴含、包藏。万物尽然，而以是相蕴：万物皆如此，以道相互蕴含为一。"},{id:"yu_ewuhu",term:"予恶乎",pinyin:"yú wū hū",meaning:"我怎么。予：我；恶乎：怎么、从哪里。呼应上段王倪「吾恶乎知之」。"},{id:"yuesheng_zhi",term:"说生之",pinyin:"yuè shēng zhī",meaning:"喜爱生存这件事。说：通「悦」，喜爱；生之：生存这件事。【通假字】说通「悦」。"},{id:"fei_huo",term:"非惑邪",pinyin:"fēi huò yé",meaning:"不是一种迷惑吗？惑：迷惑、执迷；邪：疑问语气词。"},{id:"wusi_zhi",term:"恶死之",pinyin:"wù sǐ zhī",meaning:"厌恶死亡这件事。恶：厌恶，读 wù；之：代词，指死亡。"},{id:"ruo_sang",term:"非弱丧",pinyin:"fēi ruò sàng",meaning:"不是像幼年流落在外（而不知归路）吗？弱：幼弱之时；丧：流亡、失落。弱丧：幼年流离失所，不知归处。"},{id:"guizhe",term:"归者",pinyin:"guī zhě",meaning:"回归之路、归宿。不知归者：不知道回归之路的人，喻执着于生而不知死是另一种归宿。"},{id:"liji_ren",term:"丽之姬",pinyin:"lì zhī jī",meaning:"丽地的姬（女子）。丽：地名，艾地之别称；之：助词；姬：女子。即骊姬，晋献公之宠姬。"},{id:"ai_fengren",term:"艾封人之子也",pinyin:"ài fēng rén zhī zǐ yě",meaning:"艾地守边官员的女儿。艾：地名；封人：守边疆的官员；之子：的女儿。"},{id:"jin_guo",term:"晋国之",pinyin:"jìn guó zhī",meaning:"晋国（的人）。之：助词，取消句子独立性。"},{id:"shi_dezhi",term:"始得之",pinyin:"shǐ dé zhī",meaning:"最初得到她（俘获她）的时候。始：最初；得之：得到她。"},{id:"tiqi_zhanjin",term:"涕泣沾襟",pinyin:"tì qì zhān jīn",meaning:"眼泪哭泣浸湿了衣襟。涕：眼泪；泣：哭泣；沾：浸湿；襟：衣领、衣前襟。"},{id:"ji_dengdao",term:"及",pinyin:"jí",meaning:"等到、到了。时间连词，表示到达某一时间点。"},{id:"qi_ta",term:"其",pinyin:"qí",meaning:"她。第三人称代词，指丽姬。"},{id:"zhi_daoda",term:"至",pinyin:"zhì",meaning:"到达、抵达。动词。"},{id:"yu_jie",term:"于",pinyin:"yú",meaning:"到、在。介词，引出处所。"},{id:"wangsuo",term:"王所",pinyin:"wáng suǒ",meaning:"国君的住所、宫殿。所：处所、地方。"},{id:"yu_gen",term:"与",pinyin:"yǔ",meaning:"和、跟。介词，引出共同行为的对象。"},{id:"tong_gongtong",term:"同",pinyin:"tóng",meaning:"共同、一起。与王同筐床：与国君同享华美的床榻。"},{id:"kuangchuang",term:"筐床",pinyin:"kuāng chuáng",meaning:"精美的床榻。筐：精美、华丽；床：床榻。一说「筐」为竹编之床，华美之意。"},{id:"chuhuan2",term:"刍豢",pinyin:"chú huàn",meaning:"牲畜肉食，美食。与上段「正味」一节同词，指人间美食。"},{id:"erhou_cai",term:"而后",pinyin:"ér hòu",meaning:"然后、之后。时间连词，表示先后顺序。"},{id:"hui_qiqi",term:"悔其泣",pinyin:"huǐ qí qì",meaning:"后悔当初的哭泣。悔：后悔；其泣：她当初的哭泣。丽姬之泣→悔其泣，比喻人悦生恶死或为迷惑。"},{id:"qi_tade",term:"其",pinyin:"qí",meaning:"他（死者）的。第三人称代词，指死者。"},{id:"shi_qisheng",term:"始之蕲生乎",pinyin:"shǐ zhī qí shēng hū",meaning:"当初祈求活着这件事。始：当初；之：助词；蕲：通「祈」，祈求；生：活着。【通假字】蕲通「祈」。"},{id:"dan_zaocheng",term:"旦",pinyin:"dàn",meaning:"早晨、天亮时。旦而哭泣：天亮后（醒来）却在哭泣。"},{id:"fang_zhengzai",term:"方",pinyin:"fāng",meaning:"正当、正在。方其梦也：正当他在做梦的时候。"},{id:"zhan_zhanbu",term:"占",pinyin:"zhān",meaning:"占卜、解梦。梦之中又占其梦：在梦中又对梦进行占卜解析，喻以迷解迷，无穷无尽。"},{id:"jue_erhouzhi",term:"觉而后知",pinyin:"jué ér hòu zhī",meaning:"醒来之后才知道。觉：醒来；而后：然后；知：知晓。觉而后知其梦：醒来才知道那是梦。"},{id:"dajue",term:"大觉",pinyin:"dà jué",meaning:"大彻大悟、最终的觉醒。与「大梦」对举，只有大觉才能知道此生是大梦。"},{id:"dameng",term:"大梦",pinyin:"dà mèng",meaning:"最大的梦、人生如梦。此其大梦：这（人生）就是那场大梦。庄子以大梦喻人生执念，唯大觉者方能知之。"},{id:"qieqie_zhizhi",term:"窃窃然知之",pinyin:"qiè qiè rán zhī zhī",meaning:"自以为是地小声说自己知道了。窃窃然：窃窃私语、自以为是的样子；知之：以为自己知道。讽刺愚者在梦中自以为觉。"},{id:"jun_mu",term:"君乎·牧乎",pinyin:"jūn hū · mù hū",meaning:"（自以为是）君主啊、牧人啊。君：君主；牧：牧人、统治者。指愚者在梦中自以为是君是牧，执着于身份名分。"},{id:"guzai",term:"固哉",pinyin:"gù zāi",meaning:"真是固执啊！固：固执、顽固；哉：感叹语气词。讽刺愚者执迷不悟。"},{id:"qiu_yu_nv",term:"丘也与女",pinyin:"qiū yě yǔ rǔ",meaning:"孔丘（我）和你。丘：孔子名，长梧子以孔子自称或指孔子；女：通「汝」，你。丘也与女皆梦也：连孔子和你都在梦中。"},{id:"diaogui",term:"吊诡",pinyin:"diào guǐ",meaning:"奇异诡谲、悖论之言。吊：至、极；诡：奇异。指「予谓女梦亦梦也」这句话本身也是悖论——说你在梦中的话，本身也是梦中之言。"},{id:"wanshi_eryi",term:"万世之后而一",pinyin:"wàn shì zhī hòu ér yī",meaning:"万世之后偶然一次。而一：偶尔一次；极言遇大圣之难得。"},{id:"shi_danmu_yu",term:"是旦暮遇之也",pinyin:"shì dàn mù yù zhī yě",meaning:"那就像是早晚之间就能遇到一样（容易）。旦暮：早晚，极言时间之短；遇之：遇到大圣。万世难遇，若遇则如旦暮之近——极言大圣之珍贵与相遇之幸。"}],k=[{id:"wangliang_s1",label:"罔两问景曰……何其无特操与",sentences:[[{text:"罔两",glossary:"wangliang"},"问",{text:"景",glossary:"jing_ying"},"曰：「",{text:"曩子",glossary:"nangzi"},{text:"行",glossary:"xing_zou"},"，今子",{text:"止",glossary:"zhi_tingzhi"},"；"],[{text:"曩子",glossary:"nangzi"},{text:"坐",glossary:"zuo_zuo"},"，今子",{text:"起",glossary:"qi_qili"},"。"],[{text:"何",glossary:"he_weishenme"},{text:"其",glossary:"qi_ruci"},"无",{text:"特操",glossary:"tecao"},{text:"与",glossary:"yu_yuqi"},"？」"]]},{id:"zihua_s1",label:"景曰吾有待而然者邪……恶识所以不然",sentences:[["景曰：「吾有",{text:"待",glossary:"dai_yilai"},"而",{text:"然者",glossary:"ranzhe"},"邪？"],["吾所待又有",{text:"待",glossary:"dai_yilai"},"而",{text:"然者",glossary:"ranzhe"},"邪？"],["吾待",{text:"蛇蚹蜩翼",glossary:"she_fu_tiao_yi"},"邪？"],[{text:"恶识",glossary:"ewu_shi"},{text:"所以然",glossary:"suoyiran"},"？",{text:"恶识",glossary:"ewu_shi"},{text:"所以不然",glossary:"suoyi_buran"},"？」"]]}],P=[{id:"wangliang",term:"罔两",pinyin:"wǎng liǎng",meaning:"影子外围的淡影，即「影之影」。罔：无、虚；两：通「魉」，影外之微阴。罔两依赖影子而存在，影子依赖形体而存在，形体依赖造化而存在——层层依待，以喻「无待」之道。"},{id:"jing_ying",term:"景",pinyin:"yǐng",meaning:"影子。通「影」。【通假字】⚠️ 读 yǐng，非「景色/景象」义。形体的投影，罔两所依附的对象。"},{id:"nangzi",term:"曩子",pinyin:"nǎng zǐ",meaning:"刚才你。曩：刚才、先前；子：你，第二人称敬称。【古今异义】曩非常用字，专指「刚才/从前」。"},{id:"xing_zou",term:"行",pinyin:"xíng",meaning:"行走、移动。曩子行：刚才你在移动。"},{id:"zhi_tingzhi",term:"止",pinyin:"zhǐ",meaning:"停止、静止。今子止：现在你却停下来了。与「行」对举。"},{id:"zuo_zuo",term:"坐",pinyin:"zuò",meaning:"坐下。曩子坐：刚才你坐着。"},{id:"qi_qili",term:"起",pinyin:"qǐ",meaning:"起立、站起。今子起：现在你却站起来了。与「坐」对举。行止坐起四对，形容影子随形体变化而变化，毫无自主。"},{id:"he_weishenme",term:"何",pinyin:"hé",meaning:"为什么、怎么。疑问副词。"},{id:"qi_ruci",term:"其",pinyin:"qí",meaning:"如此、这样。副词，加强语气，表示感叹。何其：怎么这样……"},{id:"tecao",term:"特操",pinyin:"tè cāo",meaning:"独立的操守、固定的主见。特：独立、专一；操：操守、立场。无特操：没有独立的操守，指影子随形体变化，毫无自主性。"},{id:"yu_yuqi",term:"与",pinyin:"yú",meaning:"语气词，表疑问或感叹。通「欤」。【通假字】⚠️ 此处读 yú，非介词「与」。"},{id:"dai_yilai",term:"待",pinyin:"dài",meaning:"依待、依赖。有待：有所依赖。庄子核心概念：「有待」指依赖外物而存在，与「无待」（逍遥游的最高境界）相对。影依形，形依造化，造化无所待——层层追问，最终归于自化。"},{id:"ranzhe",term:"然者",pinyin:"rán zhě",meaning:"如此的原因、这样的缘故。然：如此；者：代词，指如此的原因。有待而然：有所依赖才如此。"},{id:"she_fu_tiao_yi",term:"蛇蚹蜩翼",pinyin:"shé fù tiáo yì",meaning:"蛇的鳞片、蝉的翅膀。蛇蚹：蛇腹下的鳞片，蛇依赖鳞片爬行；蜩：蝉；翼：翅膀，蝉依赖翅膀飞翔。比喻形体所依赖的自然附属物——蛇鳞与蝉翼皆非外力强加，而是自然生成。影子问：我依赖形体，就像蛇依赖鳞片、蝉依赖翅膀一样，是自然而然，非有意为之。"},{id:"ewu_shi",term:"恶识",pinyin:"wū shí",meaning:"怎么知道、哪里能知道。恶：疑问代词，怎么、哪里；识：知道、了解。"},{id:"suoyiran",term:"所以然",pinyin:"suǒ yǐ rán",meaning:"如此的原因、之所以这样的缘由。所以：……的原因；然：如此。恶识所以然：怎么知道它如此的原因？"},{id:"suoyi_buran",term:"所以不然",pinyin:"suǒ yǐ bù rán",meaning:"不如此的原因、之所以不这样的缘由。与「所以然」对举，指影子对自身变化的原因一无所知，既不知为何动，也不知为何止——自化无待，莫知其所以。"}],T=[{id:"mengdie_s1",label:"昔者庄周梦为胡蝶……不知周也",sentences:[[{text:"昔者",glossary:"xizhe"},"庄周梦为胡蝶，栩栩然胡蝶也，",{text:"自喻适志与",glossary:"ziyu_shizhi"},"！不知周也。"]]},{id:"mengdie_s2",label:"俄然觉则蘧蘧然周也……胡蝶之梦为周与",sentences:[[{text:"俄然觉",glossary:"eran_jue"},"，则",{text:"蘧蘧然周也",glossary:"ququ_ran"},"。"],["不知周之梦为胡蝶",{text:"与",glossary:"yu_yuqi2"},"，胡蝶之梦为周",{text:"与",glossary:"yu_yuqi2"},"？"]]},{id:"wuhua_s1",label:"周与胡蝶则必有分矣……此之谓物化",sentences:[["周与胡蝶，则必有",{text:"分",glossary:"fen_qubie"},"矣。"],["此之谓",{text:"物化",glossary:"wuhua"},"。"]]}],v=[{id:"xizhe",term:"昔者",pinyin:"xī zhě",meaning:"从前、过去某时。昔：过去；者：助词，表时间。【古今异义】非单纯「昨天」，泛指过去某个时候。"},{id:"ziyu_shizhi",term:"自喻适志与",pinyin:"zì yù shì zhì yú",meaning:"自得其乐、心意畅适啊！自喻：自我满足、自得；适志：心意畅快满足；与：语气词，表感叹，通「欤」。【通假字】与通「欤」。全句：完全沉浸于蝴蝶的自在状态中，心意畅适，浑然忘我。"},{id:"eran_jue",term:"俄然觉",pinyin:"é rán jué",meaning:"忽然醒来。俄然：忽然、顷刻间；觉：醒来。与上段「俄而有无矣」的「俄」同义，强调转变之突然。"},{id:"ququ_ran",term:"蘧蘧然周也",pinyin:"qú qú rán zhōu yě",meaning:"惊然发现自己是庄周。蘧蘧然：惊觉、骤然清醒的样子；周：庄周。与「栩栩然胡蝶也」对举——梦中栩栩然为蝶，醒来蘧蘧然为周，两种状态同样真实。"},{id:"yu_yuqi2",term:"与",pinyin:"yú",meaning:"语气词，表疑问。通「欤」。【通假字】⚠️ 读 yú，非介词「与」。两个「与」字连用，构成庄子最著名的哲学之问。"},{id:"fen_qubie",term:"分",pinyin:"fēn",meaning:"区分、界限。必有分：必然有区别（周是周，蝶是蝶）。然而这个「分」恰恰引出「物化」——有分，却又在梦与觉之间相互转化，分而不分。"},{id:"wuhua",term:"物化",pinyin:"wù huà",meaning:"万物的转化、物我之间的相互变化。物：万物；化：变化、转化。庄子以周蝶互梦说明：万物之间虽有形态之分，却可相互转化，无绝对界限。物化是《齐物论》的终极结论——齐物之极，即物我俱化，无彼无此。呼应全篇：天籁自化→真宰无形→大梦无觉→罔两无待→物化无分。"}];return(A,n)=>{const G=y("DaoReadingPrelude"),t=y("DaoTextReading"),s=y("DaoKeywordCards"),g=y("DaoLineGuide");return D(),S("div",null,[n[0]||(n[0]=r('<h1 id="庄子·齐物论" tabindex="-1">庄子·齐物论 <a class="header-anchor" href="#庄子·齐物论" aria-label="Permalink to &quot;庄子·齐物论&quot;">​</a></h1><h2 id="篇名释义" tabindex="-1">篇名释义 <a class="header-anchor" href="#篇名释义" aria-label="Permalink to &quot;篇名释义&quot;">​</a></h2><blockquote><p><strong>「齐物论」历来有两种读法：</strong></p><ul><li><strong>齐·物论</strong>：齐平万物的各种言论——让一切「是非之辩」归于平等</li><li><strong>齐物·论</strong>：关于「齐物」的论述——万物本为一体，无所谓彼此高下</li></ul><p>两种读法，都是庄子要说的。本篇是《庄子》内七篇中哲学密度最高的一篇，也是理解庄子思想的核心入口。</p></blockquote>',3)),a(G,{title:"从地籁天籁到庄周梦蝶，进入庄子的齐物之境",summary:"齐物论是《庄子》内篇第二篇，也是全书哲学浓度最高的篇章之一。从南郭子綦的「吾丧我」开篇，到庄周梦蝶收束，庄子一层层拆解是非、彼我、梦觉之间的对立，最后提出「天地与我并生，万物与我为一」的齐物境界。",points:[{label:"先看",text:"顺着三籁→大知小知→道枢→梦蝶的人物与意象链条走一遍。"},{label:"再问",text:"庄子为什么反复拆解是非？「莫若以明」到底在说什么？"},{label:"最后",text:"庄周梦蝶不是逃避现实，而是对「我是谁」的最深追问。"}],hint:"齐物论哲学浓度很高，第一次读不必逐句求通，先把几个核心意象（地籁天籁、道枢、环中、物化、梦蝶）立住。"}),n[1]||(n[1]=i("h2",{id:"一、南郭子綦·吾丧我",tabindex:"-1"},[e("一、南郭子綦·吾丧我 "),i("a",{class:"header-anchor",href:"#一、南郭子綦·吾丧我","aria-label":'Permalink to "一、南郭子綦·吾丧我"'},"​")],-1)),n[2]||(n[2]=i("h3",{id:"原文",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:m,glossary:o,"default-mode":"classic","aria-label":"齐物论·南郭子綦吾丧我 原文"}),n[3]||(n[3]=i("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"隐机",pinyin:["yǐn","jī"],meaning:"靠着几案。隐：倚靠；机：古代低矮的小桌几，供凭倚用。"},{term:"嘘",pinyin:["xū"],meaning:"缓缓吐气，长叹。气息悠长地呼出，非急促喷气。"},{term:"苔焉",pinyin:["tái","yān"],meaning:"枯槁失神的样子。一说作「荅焉」，怅然若失貌。两说均通。"},{term:"丧其耦",pinyin:["sàng","qí","ǒu"],meaning:"失去了与自己相对的那个「我」。耦：对偶，指与形体相对的、执着于是非的那个自我。"},{term:"槁木",pinyin:["gǎo","mù"],meaning:"枯干的木头。槁：干枯。形容形体毫无生气。"},{term:"死灰",pinyin:["sǐ","huī"],meaning:"熄灭后的冷灰，不再有任何火星。形容心如止水。"},{term:"偃",pinyin:["yǎn"],meaning:"颜成子游的字。古人以字相称，表示亲近。"},{term:"女",pinyin:["rǔ"],meaning:"同「汝」，你。先秦文献常用写法。"},{term:"籁",pinyin:["lài"],meaning:"从孔穴中发出的声音，泛指一切声响。"}]}),n[4]||(n[4]=i("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"吾丧我，是全篇的钥匙",subtitle:"「我」执着于是非好恶，「吾」是与天地同在的存在；放下「我」，才能听见天籁。",lines:[{text:"今者吾丧我，汝知之乎？",tone:"钥匙",guide:"这是全篇的钥匙，也是庄子在开篇就抛出的最大谜题。「我」：执着于是非、好恶、成见的那个自我；「吾」：更深处的、与天地同在的那个存在。「吾丧我」= 放下了执着于是非的「我」，才能进入更深的听觉——从人籁，到地籁，到天籁。"},{text:"女闻人籁而未闻地籁，女闻地籁而未闻天籁夫！",tone:"三籁",guide:"三层递进，是庄子对认知层次的隐喻：人籁是人造的声音（有主使者），地籁是风吹万窍（有外力），天籁是万物各自发声、无人主使（道的层次）。「丧我」是进入天籁的前提。"}]}),n[5]||(n[5]=i("h2",{id:"二、天籁·地籁·人籁",tabindex:"-1"},[e("二、天籁·地籁·人籁 "),i("a",{class:"header-anchor",href:"#二、天籁·地籁·人籁","aria-label":'Permalink to "二、天籁·地籁·人籁"'},"​")],-1)),n[6]||(n[6]=i("h3",{id:"原文-1",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:h,glossary:l,"default-mode":"classic","aria-label":"齐物论·天籁地籁人籁 原文"}),n[7]||(n[7]=i("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"大块",pinyin:["dà","kuài"],meaning:"大地，天地自然。庄子对自然整体的亲切称呼。"},{term:"噫气",pinyin:["yī","qì"],meaning:"吐气、呼气。这里指大地呼出之气，即风的来源。"},{term:"怒呺",pinyin:["nù","háo"],meaning:"猛烈呼啸。怒：猛烈；呺：大声呼叫。"},{term:"翏翏",pinyin:["liù","liù"],meaning:"风声悠长绵延的样子。"},{term:"畏佳",pinyin:["wēi","cuī"],meaning:"高大茂密的样子。畏通「巍」，佳通「崔」。"},{term:"笄",pinyin:["jī"],meaning:"古代固定发髻的簪子。这里形容细长的孔穴。"},{term:"臼",pinyin:["jiù"],meaning:"舂米用的石器，中间有圆形凹坑。这里形容圆形凹穴。"},{term:"謞",pinyin:["xiāo"],meaning:"箭矢飞过的呼啸声，尖锐的风声。"},{term:"譹",pinyin:["háo"],meaning:"大声哭号、呼叫的声音。"},{term:"宎",pinyin:["yǎo"],meaning:"深远幽长、低沉绵延的声音。"},{term:"唱于·唱喁",pinyin:["chàng","yú","·","chàng","yú"],meaning:"象声词，形容风声一唱一和，前后呼应。"},{term:"泠风",pinyin:["líng","fēng"],meaning:"小风，微风。"},{term:"飘风",pinyin:["piāo","fēng"],meaning:"大风，疾风。"},{term:"厉风济",pinyin:["lì","fēng","jì"],meaning:"烈风停息。济：止，停歇。"},{term:"调调之刁刁",pinyin:["diào","diāo"],meaning:"树枝摇曳、叶片颤动的样子。"},{term:"比竹",pinyin:["bǐ","zhú"],meaning:"并排的竹管，即排箫一类的管乐器。人为制作，是「人籁」的典型。"},{term:"咸其自取",pinyin:["xián","qí","zì","qǔ"],meaning:"各自取用自己本有的声音。咸：都，全部。"},{term:"怒者其谁",pinyin:["nù","zhě","qí","shuí"],meaning:"是谁在激发、鼓动它们发声？怒：激发、鼓动（非愤怒义）。"}]}),n[8]||(n[8]=i("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"万物各自成声，无人主使",subtitle:"风不刻意，却吹动了一切；天籁的本质是万物自然而然、无人主使的状态。",lines:[{text:"是唯无作，作则万窍怒呺。",tone:"无作",guide:"「无作」是道的常态——不动则已。一旦动，则万物皆响应。这是庄子对「无为而无不为」最生动的自然注脚：风不刻意，却吹动了一切。"},{text:"夫吹万不同，而使其自己也。咸其自取，怒者其谁邪？",tone:"天籁",guide:"这是天籁的定义，也是全章的核心。「吹万不同」：万物各有其声；「使其自己」：都是它们自己发出来的，没有外力强迫；「咸其自取」：各自取用自己本有的声音；「怒者其谁」：那个在背后鼓动的，是谁？——没有谁。天籁的本质不是某种特别的声音，而是万物自然而然、无人主使的状态。这与道德经「道法自然」直接呼应。"}]}),n[9]||(n[9]=i("h2",{id:"三、心斗·真宰·真君",tabindex:"-1"},[e("三、心斗·真宰·真君 "),i("a",{class:"header-anchor",href:"#三、心斗·真宰·真君","aria-label":'Permalink to "三、心斗·真宰·真君"'},"​")],-1)),n[10]||(n[10]=i("h3",{id:"原文-2",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:d,glossary:u,"default-mode":"classic","aria-label":"齐物论·心斗真宰真君 原文"}),n[11]||(n[11]=i("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"大知闲闲",pinyin:["dà","zhì","xián","xián"],meaning:"大智慧者心胸宽广从容。闲闲：宽舒自在貌。知通「智」。"},{term:"小知间间",pinyin:["xiǎo","zhì","jiàn","jiàn"],meaning:"小聪明者处处分别计较。间间：分别、挑剔貌。"},{term:"大言炎炎",pinyin:["dà","yán","yán","yán"],meaning:"大言论光明盛大，气势磅礴。炎炎：盛大明亮貌。"},{term:"小言詹詹",pinyin:["xiǎo","yán","zhān","zhān"],meaning:"小言论喋喋不休，琐碎繁杂。詹詹：多言絮叨貌。"},{term:"缦者",pinyin:["màn","zhě"],meaning:"迟缓拖沓的心态。缦：缓慢、散漫。"},{term:"窖者",pinyin:["jiào","zhě"],meaning:"深藏阴险的心态。窖：地窖，深藏不露。"},{term:"密者",pinyin:["mì","zhě"],meaning:"细密周到的心态。密：细密严谨。"},{term:"惴惴",pinyin:["zhuì","zhuì"],meaning:"忧惧不安、战战兢兢的样子。"},{term:"缦缦",pinyin:["màn","màn"],meaning:"漫无边际，形容大恐惧弥漫全身，茫然失措。"},{term:"机栝",pinyin:["jī","guā"],meaning:"弩机上的扳机装置。比喻心机一触即发。"},{term:"诅盟",pinyin:["zǔ","méng"],meaning:"诅咒发誓、立盟约束。比喻固守成见，死守不放。"},{term:"缄",pinyin:["jiān"],meaning:"封口。比喻心灵封闭，如被缄封的器物。"},{term:"老洫",pinyin:["lǎo","xù"],meaning:"衰老枯竭。洫：沟渠干涸，引申为枯竭。"},{term:"姚佚启态",pinyin:["yáo","yì","qǐ","tài"],meaning:"轻浮放纵、各种情态显露。姚：轻盈；佚：放纵。"},{term:"蒸成菌",pinyin:["zhēng","chéng","jūn"],meaning:"湿气蒸腾滋生菌菇。比喻情绪在内心悄然滋长。"},{term:"真宰",pinyin:["zhēn","zǎi"],meaning:"真正的主宰。庄子追问：背后究竟有没有一个真正在主宰一切的东西？"},{term:"眹",pinyin:["zhèn"],meaning:"迹象、征兆、端倪。不得其眹：找不到任何踪迹。"},{term:"百骸",pinyin:["bǎi","hái"],meaning:"全身所有骨骼，泛指整个身体。"},{term:"六藏",pinyin:["liù","zàng"],meaning:"六脏。藏通「脏」。"},{term:"赅",pinyin:["gāi"],meaning:"完备、齐全。赅而存焉：完整地都在那里。"},{term:"相刃相靡",pinyin:["xiāng","rèn","xiāng","mí"],meaning:"相互摩擦碰撞消耗。刃：割伤；靡：磨损。"},{term:"役役",pinyin:["yì","yì"],meaning:"劳苦奔波，不得休息。"},{term:"苶然",pinyin:["niè","rán"],meaning:"疲惫困顿、精神萎靡的样子。"},{term:"芒",pinyin:["máng"],meaning:"迷茫、无所知觉、懵然无知。"}]}),n[12]||(n[12]=i("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"日以心斗，真宰无形",subtitle:"庄子冷静诊断：我们以为在生活，其实每天都在「心斗」；真宰有情而无形。",lines:[{text:"与接为构，日以心斗。",tone:"心斗",guide:"「构」：纠缠、交战。每天与外物接触，就是每天在用心打仗。庄子在这里做了一个冷静的诊断：我们以为自己在「生活」，其实每天都在「心斗」。"},{text:"其发若机栝，其司是非之谓也；其留如诅盟，其守胜之谓也。",tone:"是非",guide:"两个比喻，解剖「心斗」的两种形态：若机栝——心机发动，一触即发，这是在裁判是非；如诅盟——执念死守，如盟誓不退，这是在坚持必胜。是非与胜负，是人心日常消耗的两大引擎。"},{text:"日夜相代乎前而莫知其所萌。已乎，已乎！",tone:"叹息",guide:"喜怒哀乐，日夜轮替，没有人知道它们从哪里冒出来。「已乎，已乎」——庄子的叹息。不是绝望，是一种清醒的悲悯：我们对自己内心的来源，其实一无所知。"},{text:"若有真宰，而特不得其眹。可行己信，而不见其形，有情而无形。",tone:"真宰",guide:"这是庄子对「真宰」最精准的描述：它的作用可以感知（可行己信），却看不见它的形体（不见其形），有情实，却无形体。这个「真宰」，就是道。道不是一个具体的存在，但它的作用无处不在。"},{text:"终身役役而不见其成功，苶然疲役而不知其所归，可不哀邪！",tone:"悲叹",guide:"庄子在这里发出了一声真正的悲叹——不是对某个人，而是对人类普遍的处境：终身奔波，不见成果，不知归处。这不是悲观，这是庄子在逼我们问自己：我究竟在为什么而活？"},{text:"人之生也，固若是芒乎？其我独芒，而人亦有不芒者乎？",tone:"追问",guide:"全段以一个开放的问题收尾：人活着，难道本来就是这样迷茫的吗？还是有人，是不迷茫的？这个问题，庄子没有给答案。他把它留给了读者。"}]}),n[13]||(n[13]=i("h2",{id:"四、成心·是非·道枢",tabindex:"-1"},[e("四、成心·是非·道枢 "),i("a",{class:"header-anchor",href:"#四、成心·是非·道枢","aria-label":'Permalink to "四、成心·是非·道枢"'},"​")],-1)),n[14]||(n[14]=i("h3",{id:"原文-3",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:p,glossary:x,"default-mode":"classic","aria-label":"齐物论·成心是非道枢 原文"}),n[15]||(n[15]=i("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"成心",pinyin:["chéng","xīn"],meaning:"已经形成的固定心见、先入之见。庄子认为成心是一切是非之争的根源。"},{term:"知代",pinyin:["zhī","dài"],meaning:"懂得事物的更替变化。代：更替、交替。"},{term:"适越",pinyin:["shì","yuè"],meaning:"前往越国。适：前往。比喻颠倒时序、以无为有的荒谬。"},{term:"神禹",pinyin:["shén","yǔ"],meaning:"神明如大禹。代指最高的智慧与能力。"},{term:"鷇音",pinyin:["kòu","yīn"],meaning:"雏鸟的叫声。鷇：刚破壳的小鸟。庄子以此追问：人的言论与雏鸟叫声，本质上有区别吗？"},{term:"小成",pinyin:["xiǎo","chéng"],meaning:"小小的成就、局部的得失。道被小成所遮蔽：执着于局部，看不见整体的道。"},{term:"荣华",pinyin:["róng","huá"],meaning:"华美的辞藻、浮华的言辞。言辞越华美，离真实越远。"},{term:"儒墨",pinyin:["rú","mò"],meaning:"儒家与墨家。战国两大显学，彼此是非之争最为激烈。"},{term:"以明",pinyin:["yǐ","míng"],meaning:"用心灵的明觉来观照，不执着于是非两端。庄子的核心方法论。"},{term:"彼是方生",pinyin:["bǐ","shì","fāng","shēng"],meaning:"彼与是相互依存而生。方：并，同时。没有彼就没有是，没有是就没有彼。"},{term:"道枢",pinyin:["dào","shū"],meaning:"道的枢纽。枢：门轴，转动的中心。得道枢，即超越彼是两端、居于中心。"},{term:"环中",pinyin:["huán","zhōng"],meaning:"圆环的中心。居于环中，可以应对无穷变化而不偏执一端。"},{term:"莛与楹",pinyin:["tíng","yǔ","yíng"],meaning:"莛：细草茎；楹：大屋柱。极小与极大的对比，在道看来无差别。"},{term:"厉与西施",pinyin:["lì","yǔ","xī","shī"],meaning:"厉：丑陋之人；西施：著名美女。极丑与极美的对比，在道看来无差别。"},{term:"恢诡谲怪",pinyin:["huī","guǐ","jué","guài"],meaning:"宏大奇异、诡谲怪诞的种种事物。"}]}),n[16]||(n[16]=i("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"成心是是非之根，道枢居于环中",subtitle:"是非的根源不在外部，在于每个人心里那个先入为主的「成心」。",lines:[{text:"夫随其成心而师之，谁独且无师乎？",tone:"成心",guide:"「成心」是庄子造的概念——每个人心里已经形成的固定见解。庄子说：你顺着自己的成见去判断，谁没有这样的「老师」呢？是非的根源，不在外部，在于每个人心里那个先入为主的「成心」。连愚者也有成心，成心人人皆有，所以是非之争永无止境。"},{text:"道隐于小成，言隐于荣华。故有儒墨之是非。",tone:"遮蔽",guide:"两个「隐」，点出是非之争的根本原因：道被「小成」遮蔽——人执着于局部的对错，看不见整体；言被「荣华」掩盖——言辞越华丽，离真实越远。因此才有了儒墨之争——各执一端，以己之是为彼之非。"},{text:"彼是莫得其偶，谓之道枢。枢始得其环中，以应无穷。",tone:"道枢",guide:"这是庄子给出的解法：彼与是，互为对立；当彼与是找不到对立面时，就到了「道枢」。道枢居于环中——不偏向任何一端，因此能应对无穷的变化。类比：门轴不随门板左右摆动，正因为它在中心，才能让门自由转动。"},{text:"道行之而成，物谓之而然。",tone:"命名",guide:"两句话，说透了「道」与「名」的本质：道，走过去就成了路，不是先有路再走，是走出来的；名，事物被称呼了才成了那个样子，名是人加上去的。故莛与楹、厉与西施的差别，是人的成心加上去的。在道看来，道通为一。"}]}),n[17]||(n[17]=i("h2",{id:"五、道通为一·朝三暮四",tabindex:"-1"},[e("五、道通为一·朝三暮四 "),i("a",{class:"header-anchor",href:"#五、道通为一·朝三暮四","aria-label":'Permalink to "五、道通为一·朝三暮四"'},"​")],-1)),n[18]||(n[18]=i("h3",{id:"原文-4",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:z,glossary:_,"default-mode":"classic","aria-label":"齐物论·道通为一朝三暮四 原文"}),n[19]||(n[19]=i("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"寓诸庸",pinyin:["yù","zhū","yōng"],meaning:"寄托于平凡日常之用。庸：平常、日用。安于平常，反而得道。"},{term:"适得",pinyin:["shì","dé"],meaning:"恰好得到，刚刚好。适：恰好。"},{term:"狙公",pinyin:["jū","gōng"],meaning:"养猴人。狙：猕猴。"},{term:"赋芧",pinyin:["fù","xù"],meaning:"分发橡子。赋：分给；芧：橡树果实，即橡子。"},{term:"天钧",pinyin:["tiān","jūn"],meaning:"天道的均衡。钧：制陶转轮，引申为均衡、平衡。"},{term:"两行",pinyin:["liǎng","xíng"],meaning:"是非两端并行不悖，不执着于任何一端。圣人的处世方式。"},{term:"封",pinyin:["fēng"],meaning:"界限、边界。未始有封：从来没有界限，万物浑然一体。"},{term:"昭文",pinyin:["zhāo","wén"],meaning:"古代著名琴师。以善弹琴著称。"},{term:"师旷",pinyin:["shī","kuàng"],meaning:"春秋晋国著名乐师，精通音律。枝策：击节打拍子。"},{term:"惠子",pinyin:["huì","zǐ"],meaning:"惠施，战国名家代表，庄子的好友兼论辩对手。据梧：倚靠梧桐树论辩时的姿态。"},{term:"坚白",pinyin:["jiān","bái"],meaning:"名家著名论题「坚白石」之辩。庄子认为此类辩论是执着于小成的典型。"},{term:"纶",pinyin:["lún"],meaning:"这里指昭文的琴学传承。其子以继承父业终其一生。"},{term:"滑疑之耀",pinyin:["gǔ","yí","zhī","yào"],meaning:"消弭疑惑的光明。滑通「汩」，消弭；耀：光明、明觉。"}]}),n[20]||(n[20]=i("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"无成与毁，复通为一",subtitle:"成与毁不是绝对的，最终复通为一；名实未亏而喜怒为用，是成心在作祟。",lines:[{text:"其分也，成也；其成也，毁也。凡物无成与毁，复通为一。",tone:"循环",guide:"三句话构成一个循环：分离 → 是另一种成就；成就 → 是另一种毁坏。故成与毁不是绝对的，最终复通为一。这是庄子对「变化」最根本的看法——没有永恒的成，也没有永恒的毁，执着于任何一端都是「成心」在作祟。"},{text:"庸也者，用也；用也者，通也；通也者，得也。适得而几矣。",tone:"递进",guide:"四个递进，层层推导：庸（平常）→ 用（真正的用）→ 通（相通）→ 得（得道）。「适得而几矣」：恰好得到了，就接近道了。不追求特殊，安于平常，反而是最近道的路。"},{text:"名实未亏而喜怒为用，亦因是也。",tone:"成心",guide:"朝三暮四的寓言，核心在这一句：橡子的总数（实）没变，名称的顺序（名）也只是调换——但猴子的喜怒却被完全左右。「因是也」：这也是「成心」在起作用——被名相牵着走，不知实质未变。"},{text:"是非之彰也，道之所以亏也。道之所以亏，爱之所以成。",tone:"因果",guide:"两个因果，环环相扣：是非越彰显 → 道越亏损；道越亏损 → 偏爱越形成。「爱」：偏爱、执着。有了是非，就有了偏爱；有了偏爱，就离道越来越远。昭文鼓琴、惠子论辩，都是「爱之所以成」的例子——才华越高，执着越深。"},{text:"为是不用而寓诸庸，此之谓「以明」。",tone:"以明",guide:"全章收尾，点出「以明」的真正含义：不执着于特定的用途，寄托于平凡——这不是消极，而是不被成心驱动、不被是非左右的清醒状态。"}]}),n[21]||(n[21]=i("h2",{id:"六、葆光·八德·大辩不言",tabindex:"-1"},[e("六、葆光·八德·大辩不言 "),i("a",{class:"header-anchor",href:"#六、葆光·八德·大辩不言","aria-label":'Permalink to "六、葆光·八德·大辩不言"'},"​")],-1)),n[22]||(n[22]=i("h3",{id:"原文-5",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:b,glossary:w,"default-mode":"classic","aria-label":"齐物论·葆光八德大辩不言 原文"}),n[23]||(n[23]=i("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"秋豪之末",pinyin:["qiū","háo","zhī","mò"],meaning:"秋天新生兽毛的末梢，极细极小之物。豪通「毫」。大小是相对的。"},{term:"殇子",pinyin:["shāng","zǐ"],meaning:"夭折的孩子。殇：未成年而死。寿夭是相对的。"},{term:"彭祖",pinyin:["péng","zǔ"],meaning:"传说中的长寿之人，相传活了八百岁。"},{term:"巧历",pinyin:["qiǎo","lì"],meaning:"精明的历算家，善于推算之人。"},{term:"畛",pinyin:["zhěn"],meaning:"界限、边界。道未始有封，言未始有常，有了「是」才有了畛。"},{term:"八德",pinyin:["bā","dé"],meaning:"左右、伦义、分辩、竞争，共八种区分与对立。德：这里指事物的区别界限，非道德义。"},{term:"六合",pinyin:["liù","hé"],meaning:"上下四方，即整个宇宙空间。"},{term:"忮",pinyin:["zhì"],meaning:"强悍、好胜、刚愎。大勇不忮：真正的勇敢不刻意逞强。"},{term:"天府",pinyin:["tiān","fǔ"],meaning:"天然的府库。注之不满、酌之不竭——道的本体。"},{term:"葆光",pinyin:["bǎo","guāng"],meaning:"收藏蕴蓄的光明，不显露不张扬的内在光辉。葆通「保」，收藏、蕴蓄。与道德经「和其光，同其尘」意近。"}]}),n[24]||(n[24]=i("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"天地与我并生，大辩不言",subtitle:"大小寿夭是成心加上的区分；知止其所不知，葆光不显。",lines:[{text:"天地与我并生，而万物与我为一。",tone:"齐物",guide:"齐物论最著名的命题之一。不是说「我很伟大」，而是说：从道的视角看，天地、万物、我，本来就是同一个东西。大小、寿夭、美丑，都是人的成心加上去的区分。"},{text:"故自无适有，以至于三，而况自有适有乎！无适焉，因是已！",tone:"言说",guide:"从无到有，已经数到三了（无→有→一→言→二→三……）；何况从有到有，越数越多，永远数不完。「无适焉，因是已」：不要往那个方向走，就这样顺着走吧。这是庄子对「言说」本身的反省——越说越离道，不如停下来。"},{text:"大道不称，大辩不言，大仁不仁，大廉不谦，大勇不忮。",tone:"悖论",guide:"五个「大……不……」，是庄子最精炼的悖论句式：越刻意称说道，越不是道；越刻意辩论，越说不清；越刻意表现仁，越失去仁的本质；越刻意清廉，越让人不信；越刻意逞勇，越不成其为勇。「五者圆而几向方矣」：本来是圆融的，一旦刻意追求，就趋向僵化。这是庄子对「执着」最深刻的批判。"},{text:"故知止其所不知，至矣。",tone:"知止",guide:"知道在自己不知道的地方停下来——这才是最高的境界。不是「知道得越多越好」，而是知道自己的边界在哪里。"},{text:"注焉而不满，酌焉而不竭，而不知其所由来，此之谓葆光。",tone:"葆光",guide:"葆光：往里注入而不满，从里取出而不竭，不知道它从哪里来。这是道的存在方式，也是圣人的内在状态——不显露，不张扬，却永远充盈，永远流动。与道德经「和其光，同其尘」、「为而不争」同一脉络。"}]}),n[25]||(n[25]=i("h2",{id:"七、啮缺问王倪·正处正味正色",tabindex:"-1"},[e("七、啮缺问王倪·正处正味正色 "),i("a",{class:"header-anchor",href:"#七、啮缺问王倪·正处正味正色","aria-label":'Permalink to "七、啮缺问王倪·正处正味正色"'},"​")],-1)),n[26]||(n[26]=i("h3",{id:"原文-6",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-6","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:c,glossary:j,"default-mode":"classic","aria-label":"齐物论·啮缺问王倪 原文"}),n[27]||(n[27]=i("h3",{id:"生僻字词-6",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"啮缺",pinyin:["niè","quē"],meaning:"人名，传说中的古代贤人，王倪的学生。"},{term:"王倪",pinyin:["wáng","ní"],meaning:"人名，传说中的古代贤人，啮缺之师。"},{term:"恶乎",pinyin:["wū","hū"],meaning:"哪里，怎么。「吾恶乎知之」：我哪里知道呢？"},{term:"庸讵",pinyin:["yōng","jù"],meaning:"哪里，怎么能。庸：岂；讵：怎么。"},{term:"湿寝",pinyin:["shī","qǐn"],meaning:"睡在潮湿的地方。"},{term:"偏死",pinyin:["piān","sǐ"],meaning:"半身不遂，偏瘫。"},{term:"鳅",pinyin:["qiū"],meaning:"泥鳅。"},{term:"惴栗恂惧",pinyin:["zhuì","lì","xún","jù"],meaning:"战战兢兢、恐惧不安的样子。惴：忧惧；栗：发抖；恂：恐惧。"},{term:"猨猴",pinyin:["yuán","hóu"],meaning:"猿猴。"},{term:"刍豢",pinyin:["chú","huàn"],meaning:"牲畜的肉。刍：草食动物（牛羊）；豢：谷食动物（猪狗）。"},{term:"荐",pinyin:["jiàn"],meaning:"草，野草。麋鹿食荐：麋鹿吃草。"},{term:"蝍蛆",pinyin:["jí","jū"],meaning:"蜈蚣。"},{term:"甘带",pinyin:["gān","dài"],meaning:"以蛇为美食。带：蛇。"},{term:"鸱鸦",pinyin:["chī","yā"],meaning:"猫头鹰与乌鸦。"},{term:"耆",pinyin:["qí"],meaning:"嗜好，喜欢吃。"},{term:"猨猵狙",pinyin:["yuán","biǎn","jū"],meaning:"猿、猵（一种猿）、狙（猕猴）。"},{term:"毛嫱·丽姬",pinyin:["máo","qiáng","·","lì","jī"],meaning:"古代著名美女。毛嫱：越王宠姬；丽姬：晋献公宠姬。"},{term:"决骤",pinyin:["jué","zhòu"],meaning:"奔跑逃窜。决：快速；骤：奔跑。"},{term:"樊然淆乱",pinyin:["fán","rán","xiáo","luàn"],meaning:"纷乱混杂的样子。樊然：纷乱；淆乱：混乱。"},{term:"冱",pinyin:["hù"],meaning:"冻结，极寒。河汉冱：河流冻结。"},{term:"乘云气",pinyin:["chéng","yún","qì"],meaning:"驾驭云气，与天地同游。"},{term:"骑日月",pinyin:["qí","rì","yuè"],meaning:"乘驾日月，超越时空。"}]}),n[28]||(n[28]=i("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"没有绝对的「正」，一切判断皆有立场",subtitle:"正处、正味、正色，都是从某个立场出发的判断；至人超越一切相对标准。",lines:[{text:"庸讵知吾所谓知之非不知邪？庸讵知吾所谓不知之非知邪？",tone:"解构",guide:"王倪连说三个「吾恶乎知之」，然后反问：你怎么知道我说的「知」不是「不知」？你怎么知道我说的「不知」不是「知」？这是庄子对「知」本身的解构——知与不知的边界，本身就是模糊的。王倪不是在装谦虚，而是在说：任何关于「知」的判断，都已经预设了一个立场。"},{text:"三者孰知正处？……四者孰知正味？……四者孰知天下之正色哉？",tone:"三问",guide:"三个排比追问，构成本章的核心论证：正处——人、泥鳅、猿猴，各有各的「正确居所」；正味——人、麋鹿、蜈蚣、鸱鸦，各有各的「正确食物」；正色——人认为美的毛嫱丽姬，鱼见之深潜，鸟见之高飞，麋鹿见之奔逃。结论：没有绝对的「正」，所谓正处、正味、正色，都是从某个立场出发的判断。连仁义是非，也不过是各执一端的混乱。"},{text:"死生无变于己，而况利害之端乎！",tone:"至人",guide:"这是王倪对「至人」的描述，也是本章的落点：至人连死生都不能改变他，何况利害这种小事？「乘云气，骑日月，而游乎四海之外」——这不是神话描述，而是庄子对「超越一切相对标准」的境界的诗意表达。"}]}),n[29]||(n[29]=i("h2",{id:"八、丽姬之泣·大梦",tabindex:"-1"},[e("八、丽姬之泣·大梦 "),i("a",{class:"header-anchor",href:"#八、丽姬之泣·大梦","aria-label":'Permalink to "八、丽姬之泣·大梦"'},"​")],-1)),n[30]||(n[30]=i("h3",{id:"原文-7",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-7","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:q,glossary:f,"default-mode":"classic","aria-label":"齐物论·丽姬之泣大梦 原文"}),n[31]||(n[31]=i("h3",{id:"生僻字词-7",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"瞿鹊子",pinyin:["qú","què","zǐ"],meaning:"人名，传说中的古代人物，长梧子的学生。"},{term:"长梧子",pinyin:["zhǎng","wú","zǐ"],meaning:"人名，传说中的古代贤人。"},{term:"孟浪",pinyin:["mèng","làng"],meaning:"荒诞不经、轻率随意。孟浪之言：荒唐的话。"},{term:"听荧",pinyin:["tīng","yíng"],meaning:"听了迷惑不解。荧：迷惑、眩惑。连黄帝听了都迷惑，何况孔丘。"},{term:"丘",pinyin:["qiū"],meaning:"孔子，名丘。长梧子以孔子自谦，说孔子都不足以知之。"},{term:"大早计",pinyin:["dà","zǎo","jì"],meaning:"太早打算，操之过急。"},{term:"时夜",pinyin:["shí","yè"],meaning:"司晨报时的公鸡。见卵而求时夜：看见蛋就想要公鸡来报时，比喻操之过急。"},{term:"鸮炙",pinyin:["xiāo","zhì"],meaning:"烤猫头鹰。见弹而求鸮炙：看见弹丸就想烤猫头鹰吃，比喻想得太远。"},{term:"滑涽",pinyin:["gǔ","hūn"],meaning:"混沌、纷乱的状态。置其滑涽：把那些纷乱的东西放在一边。"},{term:"以隶相尊",pinyin:["yǐ","lì","xiāng","zūn"],meaning:"用低贱的方式来尊重彼此。隶：低贱、卑下。"},{term:"愚芚",pinyin:["yú","tún"],meaning:"浑然无知、大智若愚的样子。芚：草木初生的嫩芽，柔弱而纯朴。"},{term:"参万岁",pinyin:["cān","wàn","suì"],meaning:"综合万年的变化。参：参合、综合。"},{term:"一成纯",pinyin:["yī","chéng","chún"],meaning:"归于纯一。成纯：成就纯粹。"},{term:"说生",pinyin:["yuè","shēng"],meaning:"喜爱生命、贪生。说通「悦」。"},{term:"弱丧",pinyin:["ruò","sàng"],meaning:"幼年流离失所，忘了回家的路。比喻人执着于生，不知死是归途。"},{term:"丽之姬",pinyin:["lì","zhī","jī"],meaning:"即丽姬（丽戎之地的女子），晋献公宠姬。丽：地名，在今陕西。"},{term:"艾封人",pinyin:["ài","fēng","rén"],meaning:"艾地的守边官员。封人：守边疆的官。"},{term:"筐床",pinyin:["kuāng","chuáng"],meaning:"精美的床榻。筐：精美、华丽。"},{term:"蕲生",pinyin:["qí","shēng"],meaning:"求生、希望活着。蕲：祈求、希望。"},{term:"旦而田猎",pinyin:["dàn","ér","tián","liè"],meaning:"醒来后去打猎，精神振奋。与梦中哭泣形成对比。"},{term:"占其梦",pinyin:["zhān","qí","mèng"],meaning:"在梦中解析自己的梦。占：占卜、解析。"},{term:"大觉",pinyin:["dà","jué"],meaning:"大彻大悟，真正的觉醒。与「大梦」相对。"},{term:"窃窃然",pinyin:["qiè","qiè","rán"],meaning:"自以为是、沾沾自喜的样子。"},{term:"吊诡",pinyin:["diào","guǐ"],meaning:"奇异、诡谲。是其言也，其名为吊诡：这番话，名字叫做吊诡（奇异之论）。"}]}),n[32]||(n[32]=i("h3",{id:"核心句引读-7",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"生死皆梦，连「指出梦」也是梦",subtitle:"丽姬的眼泪与梦中之梦，解构了所有当下的确定性。",lines:[{text:"予恶乎知说生之非惑邪？予恶乎知恶死之非弱丧而不知归者邪？",tone:"生死",guide:"两个「予恶乎知」，是庄子最深沉的追问：我怎么知道贪恋生命不是一种迷惑？我怎么知道害怕死亡，不是像幼年流落他乡、忘了回家路的人一样？「弱丧而不知归」是全篇最动人的比喻之一——一个幼年就离家流浪的人，在外漂泊久了，竟忘了家在哪里。庄子说：我们对死亡的恐惧，可能正是这种状态——我们以为活着是家，其实死亡才是归处。"},{text:"丽之姬……晋国之始得之也，涕泣沾襟；及其至于王所……而后悔其泣也。",tone:"当下",guide:"丽姬的故事，是庄子对「当下判断」最精准的解构：被带走时哭得泪湿衣襟——以为是灾难；到了王宫，锦衣玉食——才后悔当初的哭泣。「予恶乎知夫死者不悔其始之蕲生乎？」死去的人，会不会也后悔当初那么拼命求生？所有当下的判断，都可能是丽姬的眼泪。"},{text:"方其梦也，不知其梦也。梦之中又占其梦焉，觉而后知其梦也。",tone:"大梦",guide:"三个层次，层层递进：梦中，不知道自己在梦里；梦中之梦，在梦里解析自己的梦；醒来，才知道那是梦。「且有大觉而后知此其大梦也」——我们现在以为自己是「醒着」的，但也许还需要一次「大觉」，才能知道这整个人生，也是一场大梦。"},{text:"丘也与女，皆梦也；予谓女梦，亦梦也。",tone:"自指",guide:"这是庄子最彻底的自我解构：孔子是梦，你是梦，我说你们在做梦——这句话本身，也是梦。没有一个站在梦外的「清醒者」，连「指出梦」这个动作，也在梦里。"},{text:"是其言也，其名为吊诡。万世之后而一遇大圣，知其解者，是旦暮遇之也。",tone:"知音",guide:"庄子最后说：这番话，名字叫「吊诡」——奇异之论。万世之后若能遇到一个真正懂得的大圣人，那就好像今天明天就能遇到一样。这句话既是谦逊，也是期许——真正的知音，不在乎时间的远近。"}]}),n[33]||(n[33]=i("h2",{id:"九、罔两问景·自化无待",tabindex:"-1"},[e("九、罔两问景·自化无待 "),i("a",{class:"header-anchor",href:"#九、罔两问景·自化无待","aria-label":'Permalink to "九、罔两问景·自化无待"'},"​")],-1)),n[34]||(n[34]=i("h3",{id:"原文-8",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-8","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:k,glossary:P,"default-mode":"classic","aria-label":"齐物论·罔两问景 原文"}),n[35]||(n[35]=i("h3",{id:"生僻字词-8",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"罔两",pinyin:["wǎng","liǎng"],meaning:"影子之外更淡的阴影，即「影外之影」，半影。"},{term:"景",pinyin:["yǐng"],meaning:"影子。古「影」字写作「景」。"},{term:"曩",pinyin:["nǎng"],meaning:"从前、刚才。曩子行：你刚才在走。"},{term:"特操",pinyin:["tè","cāo"],meaning:"固定的操守、自己的主见。何其无特操：怎么这么没有主见？"},{term:"有待",pinyin:["yǒu","dài"],meaning:"依赖某种外在条件。有待而然：因为依赖某物才这样。"},{term:"蛇蚹",pinyin:["shé","fù"],meaning:"蛇腹下的鳞片，蛇靠它爬行。"},{term:"蜩翼",pinyin:["tiáo","yì"],meaning:"蝉的翅膀，蝉靠它飞翔。"},{term:"恶识",pinyin:["wū","shí"],meaning:"哪里知道，怎么知道。"}]}),n[36]||(n[36]=i("h3",{id:"核心句引读-8",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"影子追问影子，无待而自化",subtitle:"每一个「因为」背后，还有另一个「因为」；追问「为什么」本身，已经是成心在作祟。",lines:[{text:"吾有待而然者邪？吾所待又有待而然者邪？",tone:"追问",guide:"影子反问半影：我是因为依赖某物才这样动的吗？那我所依赖的，又是依赖什么才这样的呢？这是一个无限追问的链条——每一个「因为」背后，还有另一个「因为」。追到最后，找不到一个「第一推动者」。"},{text:"吾待蛇蚹蜩翼邪？恶识所以然？恶识所以不然？",tone:"自化",guide:"蛇靠鳞片爬行，蝉靠翅膀飞翔——但蛇知道自己为什么能爬吗？蝉知道自己为什么能飞吗？它们只是自然而然地动，并不知道「所以然」。影子的意思是：万物的变化，都是如此——无待而自化，不知其所以然。追问「为什么」本身，就已经是成心在作祟。这一章极短，却是齐物论最精炼的收束之一：连影子都不知道自己为何而动，人又何必执着于「是非」的根源？"}]}),n[37]||(n[37]=i("h2",{id:"十、庄周梦蝶·物化",tabindex:"-1"},[e("十、庄周梦蝶·物化 "),i("a",{class:"header-anchor",href:"#十、庄周梦蝶·物化","aria-label":'Permalink to "十、庄周梦蝶·物化"'},"​")],-1)),n[38]||(n[38]=i("h3",{id:"原文-9",tabindex:"-1"},[e("原文 "),i("a",{class:"header-anchor",href:"#原文-9","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:T,glossary:v,"default-mode":"classic","aria-label":"齐物论·庄周梦蝶 原文"}),n[39]||(n[39]=i("h3",{id:"生僻字词-9",tabindex:"-1"},[e("生僻字词 "),i("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"胡蝶",pinyin:["hú","dié"],meaning:"蝴蝶。古作「胡蝶」。"},{term:"栩栩然",pinyin:["xǔ","xǔ","rán"],meaning:"生动活泼、自由自在的样子。"},{term:"自喻适志",pinyin:["zì","yù","shì","zhì"],meaning:"自己感到舒适惬意、心满意足。喻：通「愉」，愉快；适志：心意舒畅。"},{term:"俄然",pinyin:["é","rán"],meaning:"忽然，一会儿。"},{term:"蘧蘧然",pinyin:["qú","qú","rán"],meaning:"惊醒的样子，惶然。"},{term:"必有分",pinyin:["bì","yǒu","fēn"],meaning:"必然有区别。分：界限、区分。"},{term:"物化",pinyin:["wù","huà"],meaning:"万物自然转化、相互流变。不执着于固定形态，随道而化。"}]}),n[40]||(n[40]=i("h3",{id:"核心句引读-9",tabindex:"-1"},[e("核心句引读 "),i("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"物我边界可流动，是齐物论的终极落点",subtitle:"庄周可以化为蝴蝶，蝴蝶可以化为庄周——不是抹去差异，而是在差异中看见流动。",lines:[{text:"昔者庄周梦为胡蝶，栩栩然胡蝶也，自喻适志与！不知周也。",tone:"忘我",guide:"这是中国哲学史上最美的一段话。庄周梦见自己是蝴蝶——在梦里，他不知道自己是庄周，他就是蝴蝶，完完全全地是蝴蝶。「自喻适志」——那种自在，是真实的，不是幻觉。"},{text:"俄然觉，则蘧蘧然周也。",tone:"醒来",guide:"忽然醒来，惶然发现自己是庄周。注意「蘧蘧然」——是惊惶的，不是安然的。醒来反而有一种失落感，好像从某个更真实的地方被拽回来了。"},{text:"不知周之梦为胡蝶与，胡蝶之梦为周与？",tone:"梦觉",guide:"这是全篇最著名的一问，也是中国哲学最经典的悬案：是庄周梦见了蝴蝶？还是蝴蝶梦见了庄周？庄子没有给答案。他不是在问你选哪个，他是在说：这个问题本身无法被确定。「我」与「物」的边界，在道的层面，是可以流动的。"},{text:"周与胡蝶，则必有分矣。此之谓物化。",tone:"物化",guide:"最后一句，看似收束，实则更深：庄周与蝴蝶，当然有区别（必有分）；但这种区别，是在「物化」的流动中存在的。物化：万物不是固定的存在，而是在道中不断转化流变。不是说两者没有区别，而是说区别不是绝对的、永恒的。这正是「齐物」的最终落点——不是抹去差异，而是在差异中看见流动。"}]}),n[41]||(n[41]=r(`<h2 id="脉络逻辑链" tabindex="-1">脉络逻辑链 <a class="header-anchor" href="#脉络逻辑链" aria-label="Permalink to &quot;脉络逻辑链&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1段·起（南郭子綦·吾丧我）</span></span>
<span class="line"><span>    隐机而坐·吾丧我·人籁地籁天籁</span></span>
<span class="line"><span>    → 放下执着的我，才能听见天籁</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第2段·进（天籁·地籁·人籁）</span></span>
<span class="line"><span>    大块噫气·万窍怒呺·吹万不同咸其自取</span></span>
<span class="line"><span>    → 天籁：万物自然发声，无人主使</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第3段·析（心斗·真宰·真君）</span></span>
<span class="line"><span>    大知小知·日以心斗·若有真宰而有情无形</span></span>
<span class="line"><span>    → 诊断人心：是非与胜负消耗生命</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第4段·转（成心·是非·道枢）</span></span>
<span class="line"><span>    随其成心而师之·道隐于小成·莫若以明</span></span>
<span class="line"><span>    → 解法：居于环中，以应无穷</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第5段·承（道通为一·朝三暮四）</span></span>
<span class="line"><span>    复通为一·寓诸庸·朝三暮四·天钧两行</span></span>
<span class="line"><span>    → 从是非到齐物：名实未亏而喜怒为用</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第6段·深（葆光·八德·大辩不言）</span></span>
<span class="line"><span>    天地与我并生·大辩不言·知止其所不知</span></span>
<span class="line"><span>    → 齐物的深化：言说与不言之辩</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第7段·证（啮缺问王倪·正处正味正色）</span></span>
<span class="line"><span>    民湿寝则偏死·麋鹿食荐·毛嫱丽姬</span></span>
<span class="line"><span>    → 无绝对标准：正处正味正色皆有立场</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第8段·化（丽姬之泣·大梦）</span></span>
<span class="line"><span>    丽之姬泣涕沾襟·梦饮酒者旦而哭泣</span></span>
<span class="line"><span>    → 生死皆梦，当下判断不可恃</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第9段·省（罔两问景·自化无待）</span></span>
<span class="line"><span>    吾有待而然者邪·吾所待又有待</span></span>
<span class="line"><span>    → 无待自化：追问本身已是成心</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第10段·合（庄周梦蝶·物化）</span></span>
<span class="line"><span>    栩栩然胡蝶·蘧蘧然周·此之谓物化</span></span>
<span class="line"><span>    → 物我边界可流动——齐物论的终极落点</span></span></code></pre></div><p><strong>全篇主线</strong>：从「吾丧我」开篇，经三籁、心斗、成心是非的层层拆解，立道枢环中，证道通为一，再经正处正味正色、大梦、罔两问景，最终收于庄周梦蝶——物化，是齐物的完成。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="一、字面说了什么" tabindex="-1">一、字面说了什么？ <a class="header-anchor" href="#一、字面说了什么" aria-label="Permalink to &quot;一、字面说了什么？&quot;">​</a></h3><p>齐物论从一个「吾丧我」的悬案开始。南郭子綦进入一种放下自我的状态，引出人籁、地籁、天籁三层追问——万物各自成声，无人主使。随后庄子拆解「大知小知」「成心」「真宰」：人如何在外物接触、情绪与成见中，自设是非、日以心斗。</p><p>中段进入全篇的哲学枢纽。彼与是、可与不可在相待中生起，于是提出「道枢」「环中」与「莫若以明」。朝三暮四、啮缺问王倪，接连拆开人把自身好恶、利害与习惯当作天下标准的冲动。</p><p>最后，大梦大觉、罔两问景与庄周梦蝶，把问题从是非推进到自我与变化。庄周没有宣告一切没有差别，而是保留「周与胡蝶，则必有分矣」的分际，同时让读者看见身份、梦觉与万物都在不断物化。</p><h3 id="二、背后的逻辑是什么" tabindex="-1">二、背后的逻辑是什么？ <a class="header-anchor" href="#二、背后的逻辑是什么" aria-label="Permalink to &quot;二、背后的逻辑是什么？&quot;">​</a></h3><p>齐物论的逻辑是「破执」的三层递进：</p><p><strong>第一层：破「成心」</strong></p><p>是非的根源不在外部，在于每个人心里那个先入为主的「成心」。儒墨之争、朝三暮四，都是成心在作祟。</p><p><strong>第二层：立「道枢」</strong></p><p>不执着于是非两端，居于环中，以明观照。道通为一——莛与楹、厉与西施，在道看来无差别。</p><p><strong>第三层：化「物我」</strong></p><p>正处、正味、正色皆无绝对标准。生死是大梦，物我可流化——庄周梦蝶，此之谓物化。</p><h3 id="三、这对我们意味着什么" tabindex="-1">三、这对我们意味着什么？ <a class="header-anchor" href="#三、这对我们意味着什么" aria-label="Permalink to &quot;三、这对我们意味着什么？&quot;">​</a></h3><p>齐物论不是在说「一切皆假」，也不是要人失去判断。它要松开的，是把一己立场绝对化的冲动：知道判断从哪里来，反而更能谨慎地判断。</p><p>庄子的逍遥，不是不做事，而是做事时心里没有那个「不得不」。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><p><strong>关于成心</strong></p><blockquote><p>我们每天刷到的信息流，本质上是一台「成心制造机」。算法不断投喂你已经相信的东西，让你的成心越来越厚、越来越硬。庄子的解法不是「多看不同观点」，而是更根本的——把那个「判断者」本身放下。</p></blockquote><p><strong>关于道枢</strong></p><blockquote><p>现代人最缺的不是立场，而是「居于环中」的能力。不是「我不表态」，而是「我能同时持有两端，而不被任何一端绑架」。这是一种极高的心理弹性，也是庄子说的「以明」。</p></blockquote><p><strong>关于大梦</strong></p><blockquote><p>丽姬哭着被带走，后来悔恨当初的眼泪。我们有多少「当下的确信」，会在未来变成「丽姬的眼泪」？庄子不是要你虚无，而是要你对当下的判断保持一份轻盈——拿得起，也放得下。</p></blockquote><p><strong>关于物化</strong></p><blockquote><p>庄周梦蝶，是庄子送给我们最后的礼物。不是一个答案，而是一个姿势——在「我是谁」这个问题上，保持开放，不急着钉死。你现在的身份、角色、立场，都是「周」，都是「蝴蝶」，都在物化之中。</p></blockquote><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关键词</th><th>所在章节</th><th>一句话释义</th></tr></thead><tbody><tr><td>吾丧我</td><td>一</td><td>放下社会化的自我，回归本真</td></tr><tr><td>天籁</td><td>二</td><td>万物自然呈现，非人为吹出</td></tr><tr><td>成心</td><td>四</td><td>先入为主的固定见解，是非之根</td></tr><tr><td>道枢·环中</td><td>四</td><td>超越彼是两端，居于中心以应无穷</td></tr><tr><td>以明</td><td>四·五</td><td>不被成心驱动的心灵明觉</td></tr><tr><td>道通为一</td><td>四·五</td><td>万物差异在道的层面归于统一</td></tr><tr><td>朝三暮四</td><td>五</td><td>名实未亏而被名相左右，成心之喻</td></tr><tr><td>两行</td><td>五</td><td>是非两端并行不悖，圣人的处世方式</td></tr><tr><td>葆光</td><td>六</td><td>不显露不张扬的内在充盈</td></tr><tr><td>大辩不言</td><td>六</td><td>越刻意辩论，越说不清真实</td></tr><tr><td>正处·正味·正色</td><td>七</td><td>无绝对标准，一切判断皆有立场</td></tr><tr><td>至人</td><td>七</td><td>超越利害生死，乘云气骑日月</td></tr><tr><td>大梦</td><td>八</td><td>人生如梦，连「指出梦」也是梦</td></tr><tr><td>丽姬之泣</td><td>八</td><td>当下的判断可能是未来后悔的眼泪</td></tr><tr><td>物化</td><td>十</td><td>万物在道中不断流变转化，无绝对边界</td></tr><tr><td>庄周梦蝶</td><td>十</td><td>物我边界可流动，是齐物论的终极落点</td></tr></tbody></table><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《庄子》</li></ul>`,32))])}}});export{E as __pageData,I as default};
